/**
 * Seed Vertical Drama Series genre presets (spec feature 131 UI addendum).
 * Run with: npx tsx scripts/seed-vertical-drama-genre-presets.ts
 *
 * Idempotent: clears all existing rows in vertical_drama_genre_presets before
 * inserting, so this is safe to re-run after editing the preset list below.
 */

import postgres from "postgres";

const DATABASE_URL = process.env.DATABASE_URL || "postgresql://smartspec:smartspec123@localhost:5432/smartspec";

interface GenrePresetCharacter {
  name: string;
  role: string;
  description: string;
}

/**
 * Structured visual identity (spec §8.2.2.A / section-15) — mirrors
 * `VerticalDramaPresetVisualIdentity` in
 * `shared/verticalDramaSeries/presetVisualIdentity.ts` structurally. Kept as
 * a LOCAL interface (not imported) so this standalone `postgres`-driver
 * script keeps its existing self-contained convention (see
 * `GenrePresetSeed`/`GenrePresetCharacter` above, also local).
 */
interface GenrePresetVisualIdentitySeed {
  styleName: string;
  /** 3-6 dominant colors (names or hex). */
  palette: string[];
  lighting: string;
  environmentMotifs: string[];
  wardrobeGrammar: string[];
  signaturePropsAndCompanions: string[];
  cameraGrammar: string;
  characterArchetypes: Array<{ role: string; look: string }>;
  imagePromptFragments: {
    positive: string[];
    negative: string[];
  };
}

interface GenrePresetSeed {
  title: string;
  category: string;
  logline: string;
  mainPlot: string;
  seasonArc: string;
  tone: string;
  cliffhangerStyle: string;
  characters: GenrePresetCharacter[];
  visualBible: string;
  /**
   * Optional (spec §8.2.2.A, section-15) — nullable additive column.
   * Legacy presets (every entry below the `sci_fi_mecha` family) omit this
   * field entirely; the INSERT below writes `NULL` for those rows, exactly
   * like today (legacy-tolerant, byte-identical for existing presets).
   */
  visualIdentityJson?: GenrePresetVisualIdentitySeed;
}

