    "logline": "หนึ่งปีหลังเสียคู่หมั้นไป สถาปนิกสาวได้พบชายแปลกหน้าที่มีชีวิตอยู่ด้วยหัวใจที่บริจาคมาจากคู่หมั้นของเธอ ความรักครั้งใหม่จึงเริ่มต้นด้วยคำถามที่โหดที่สุด ว่าเธอรักผู้ชายคนนี้ หรือรักเสียงหัวใจในอกเขา",
    "mainPlot": "หนึ่งปีหลัง คธา คู่หมั้นนักดนตรีของ ปริม เสียชีวิตจากอุบัติเหตุบนถนนเส้นที่ทั้งคู่ใช้กลับบ้านทุกวัน ปริมยังใช้ชีวิตแบบเข็มนาฬิกาที่หยุดเดิน จนจดหมายจากศูนย์รับบริจาคอวัยวะฉบับหนึ่งหลุดมาถึงมือเธอโดยไม่ตั้งใจ ทำให้รู้ว่าหัวใจของคธาเต้นต่ออยู่ในอกของ นายแพทย์ภูวิศ ศัลยแพทย์หนุ่มใหญ่ที่เคยหยุดผ่าตัดกลางอาชีพเพราะโรคหัวใจของตัวเอง ปริมตั้งใจแค่ไปดูให้เห็นสักครั้งว่าหัวใจดวงนั้นยังเต้นอยู่จริง แต่กลับพลั้งกลายเป็นสถาปนิกผู้รับงานรีโนเวตคลินิกชุมชนของภูวิศโดยไม่เปิดเผยว่าตัวเองเป็นใคร ยิ่งทำงานด้วยกัน เธอยิ่งพบว่าภูวิศไม่ใช่เงาของคธาเลยสักนิด เขาเงียบ ขวานผ่าซาก และแบกความรู้สึกผิดของคนที่ได้มีชีวิตต่อเพราะการตายของคนอื่น ขณะที่ภูวิศเองก็เก็บความลับไว้เช่นกัน ว่าเขารู้มาตลอดว่าปริมคือใคร เพราะจดหมายขอบคุณที่เขาเขียนแล้วไม่เคยกล้าส่งสามฉบับ จ่าหน้าถึงเธอทั้งหมด เมื่อความจริงสองด้านค่อยๆ งวดเข้าหากัน ทั้งคู่ต้องตอบคำถามเดียวกันคนละมุม ว่าความรักครั้งนี้เกิดขึ้นเพราะกันและกัน หรือเพราะคนที่ตายไปเป็นคนจัดฉากไว้",
    "seasonArc": "ช่วงต้นซีซั่นเล่าการพบกันแบบต่างคนต่างซ่อนไพ่ งานรีโนเวตคลินิกที่บังคับให้สองคนขวานผ่าซากต้องปะทะกันทุกวัน สลับแฟลชแบ็กความรักของปริมกับคธาที่ค่อยๆ เผยว่าไม่ได้สมบูรณ์แบบอย่างที่เธอเลือกจำ ช่วงกลางความสัมพันธ์เริ่มข้ามเส้นเพื่อนร่วมงานพร้อมกับที่ความลับเริ่มรั่ว เมื่อน้องสาวของคธากลับจากต่างประเทศมาพบว่าปริมวนเวียนอยู่กับผู้รับหัวใจของพี่ชาย และมองว่านี่คือการทรยศคนตาย จุดพีคคือการเปิดจดหมายที่ไม่เคยส่งทั้งสามฉบับกลางงานเปิดคลินิก ที่ทำให้ปริมรู้ว่าภูวิศรู้ความจริงมาตลอด และเดินจากไปด้วยความรู้สึกถูกหลอกซ้ำสอง ตอนจบซีซั่นภูวิศล้มลงด้วยภาวะร่างกายต่อต้านหัวใจดวงใหม่ บังคับให้ปริมต้องเผชิญความกลัวที่แท้จริงของตัวเอง ว่าเธอไม่ได้กลัวการรักผิดคน แต่กลัวการสูญเสียเสียงหัวใจดวงเดิมเป็นครั้งที่สอง",
