    "mainPlot": "คืนที่ดาวตกพาดผ่านหลังคาบ้าน มะลิ เด็กหญิงวัยหกขวบพบไม้กายสิทธิ์รูปดอกมะลิตกอยู่ในกระถางต้นไม้ของคุณยายจันทร์ แต่ไม้วิเศษแท่งนี้มีกติกาไม่เหมือนในนิทานเรื่องไหน เพราะมันเสกของเล่นหรือขนมไม่ได้เลย มันจะเปล่งแสงขึ้นทีละสีก็ต่อเมื่อมะลิทำสิ่งดีๆ จากใจจริง เช่น แบ่งร่มให้เพื่อนตอนฝนตก ช่วยลูกนกกลับรัง หรือนั่งฟังเพื่อนที่กำลังเสียใจจนยิ้มได้ เมื่อแสงครบเจ็ดสี ประตูเมฆจะเปิดพามะลิและปุยฝ้าย แกะเมฆน้อยคู่หูขึ้นไปยังเมืองปุยเมฆ ดินแดนที่ความใจดีทุกครั้งของเด็กบนพื้นโลกจะงอกเงยเป็นดอกไม้แสงระยิบระยับ เสน่ห์ของเรื่องคือเวทมนตร์ที่แท้จริงไม่ได้อยู่ที่ไม้กายสิทธิ์ แต่อยู่ที่หัวใจของคนถือ และทุกตอนคือบทเรียนน้ำใจเล็กๆ ที่เด็กเอาไปทำตามได้จริงตั้งแต่ปิดจอ ยิ่งไปกว่านั้นเมืองปุยเมฆยังมีเจ้าหมอกงอแง เด็กเมฆขี้น้อยใจที่ชอบแอบบังแสงดอกไม้คนอื่น ซึ่งมะลิค่อยๆ เรียนรู้ว่าเขาไม่ใช่ตัวร้าย แค่เป็นเพื่อนที่ยังไม่มีใครชวนเล่นเท่านั้นเอง",
    "seasonArc": "ช่วงต้นมะลิค้นพบไม้กายสิทธิ์และค่อยๆ เรียนรู้กติกาเจ็ดแสงผ่านความใจดีเล็กๆ ในบ้านและโรงเรียน พร้อมขึ้นไปเยือนเมืองปุยเมฆครั้งแรกอย่างตื่นตาตื่นใจ ช่วงกลางเธอชวนก้อนแป้งเพื่อนซี้มาร่วมรู้ความลับ แต่กลับพบว่าดอกไม้แสงในเมืองปุยเมฆเริ่มหุบและสีจางลงเรื่อยๆ เพราะเจ้าหมอกงอแงแผ่หมอกสีเทาคลุมเมืองมากขึ้นทุกวัน ช่วงพีคมะลิพยายามใช้แสงทั้งเจ็ดสีขับไล่หมอกแต่ไม่สำเร็จ จนเธอวางไม้กายสิทธิ์ลงแล้วเลือกนั่งลงข้างเจ้าหมอกงอแงเฉยๆ และค้นพบว่าหมอกทั้งเมืองจางหายด้วยคำชวนง่ายๆ ว่า 'มาเล่นด้วยกันไหม' ที่ไม่ต้องใช้เวทมนตร์สักนิด ก่อนปิดซีซั่นอย่างงดงามเมื่อชาวเมืองปุยเมฆมอบเมล็ดเวทมนตร์ให้มะลิและเพื่อนๆ นำกลับมาปลูกบนพื้นโลก เพื่อให้ความใจดีงอกเงยต่อไปไม่รู้จบ",
