    "mainPlot": "ปริม นักวิจัยหลังปริญญาเอกของศูนย์ประสาทวิทยาศาสตร์แห่งอนาคตย่านชานกรุง ทุ่มทั้งชีวิตให้โครงการเอนไซม์ฟื้นฟูเซลล์สมอง เพราะแม่ของเธอป่วยเป็นอัลไซเมอร์ระยะลุกลามและเริ่มจำลูกสาวไม่ได้ เมื่อผลทดลองรอบล่าสุดออกมาดีเกินคาด ทั้งแล็บก็ตกอยู่ในความยินดีปนกดดัน เพราะทุนวิจัยก้อนมหาศาลจากบริษัทยาข้ามชาติกำลังรอเซ็นสัญญา แต่ปริมสังเกตเห็นความผิดปกติเล็กๆ ในชุดข้อมูล เหมือนมีคนแก้ตัวเลขบางค่าให้สวยขึ้น หากเธอเปิดปาก โครงการทั้งหมดอาจล่ม แม่ของเธอจะหมดโอกาสได้รับยาทันเวลา และเพื่อนร่วมแล็บทุกคนอาจตกงาน แต่ถ้าเธอเงียบ ยาที่ยังไม่ปลอดภัยอาจถูกฉีดเข้าร่างผู้ป่วยหลายพันคน ปริมจึงเริ่มสืบเงียบๆ ว่าใครแก้ข้อมูล และพบว่าความจริงพันไปถึงคนที่เธอไว้ใจที่สุดในแล็บ",
