    "mainPlot": "ดร.ข้าวฟ่าง นักปักษีวิทยาสาวกลับมายังหมู่บ้านชายป่าต้นน้ำบ้านเกิด พร้อมทุนวิจัยก้อนเล็กๆ เพื่อพิสูจน์เสียงนกปริศนาที่ชาวบ้านอัดคลิปได้ ซึ่งเธอเชื่อว่าคือนกเจ้าฟ้าหลวงที่ถูกประกาศสูญพันธุ์ไปตั้งแต่รุ่นพ่อ การพบนกเพียงคู่เดียวในหุบเขาลึกทำให้ผืนป่านี้เข้าเกณฑ์เขตอนุรักษ์เร่งด่วน และนั่นหมายถึงโครงการเหมืองแร่หมื่นล้านของตระกูลอินทรวงศ์ ผู้มีพระคุณที่ส่งเธอเรียนจนจบเมืองนอก ต้องหยุดชะงักทันที ข้าวฟ่างพบว่าตัวเองยืนอยู่ระหว่างหนี้บุญคุณกับหน้าที่นักวิทยาศาสตร์ ระหว่างเพื่อนบ้านที่รอเงินค่าเวนคืนไปใช้หนี้กับเพื่อนบ้านอีกครึ่งที่ไม่ยอมทิ้งสายน้ำ ยิ่งเมื่อผู้ช่วยวิจัยหนุ่มของเธอตรวจพบสารโลหะหนักในลำห้วยทั้งที่เหมืองยังไม่เปิด ก็ชัดว่ามีการขุดสำรวจลับมานานแล้ว และคนที่รู้เรื่องนี้ก่อนหน้าเธอคือพ่อของเธอเอง ผู้พิทักษ์ป่าที่หายตัวไปในหุบเขานี้เมื่อยี่สิบปีก่อนโดยไม่มีใครพบร่าง",
    "seasonArc": "ช่วงต้นคือการตามล่าเสียงนกกลางป่าดิบด้วยศาสตร์ภาคสนามที่ทั้งลุ้นและงดงาม จนจบด้วยภาพถ่ายนกเจ้าฟ้าหลวงที่สั่นสะเทือนทั้งวงการ ช่วงกลางแรงกดดันถาโถมจากทุกทิศ ทั้งข้อเสนอเงินก้อนโต การข่มขู่ กล้องดักถ่ายที่ถูกทุบ และหมู่บ้านที่แตกเป็นสองฝ่าย ขณะที่ข้าวฟ่างขุดลึกลงไปพบแผนที่สำรวจแร่ฉบับเก่าที่มีลายมือพ่อของเธอกำกับ จุดพีคคือการค้นพบโพรงถ้ำต้นน้ำที่ซ่อนทั้งรังนกฝูงสุดท้ายและหลักฐานว่าพ่อของเธอหายไปเพราะไปเจอการขุดลับก่อนใคร ตอนจบซีซั่นคือเวทีประชาพิจารณ์ที่ข้าวฟ่างต้องเลือกเปิดหลักฐานทั้งหมดต่อหน้าคนที่มีพระคุณ พร้อมเสียงนกเจ้าฟ้าหลวงร้องก้องหุบเขาเป็นครั้งแรกที่คนทั้งประเทศได้ยินสด",
