    "mainPlot": "หนูนา เด็กหญิงวัยเก้าขวบ ย้ายมาอยู่กับยายทวดในหมู่บ้านชายทะเลที่มีร้านเล็กๆ แสนประหลาด ผู้คนที่แบกความทรงจำหนักอึ้งเกินไปจะนำมันมาฝากไว้ในขวดแก้ว ความทรงจำจะเปล่งแสงเป็นสีต่างกันตามความรู้สึกที่บรรจุอยู่ข้างใน เมื่อยายทวดเริ่มหลงลืมมากขึ้นทุกวัน หนูนาจึงอาสาดูแลร้านแทน และได้เรียนรู้เรื่องราวของคนในหมู่บ้านผ่านขวดแต่ละใบ ทั้งชายชราที่ฝากความคิดถึงภรรยา เด็กชายที่ฝากความกลัวทะเล และครูสาวที่ฝากความฝันที่ไปไม่ถึง แต่ในตู้ลึกสุดของร้านมีขวดสีทองใบหนึ่งที่ไม่มีป้ายชื่อ ซึ่งหนูนาค่อยๆ พบว่ามันคือความทรงจำที่ยายทวดฝากไว้เอง ก่อนที่โรคหลงลืมจะพรากมันไปจริงๆ หนูนาจึงเริ่มออกเดินทางเล็กๆ ในหมู่บ้าน ตามรอยเรื่องราวในขวดสีทองเพื่อคืนความทรงจำที่งดงามที่สุดให้ยายทวดอีกครั้ง",
    "seasonArc": "ช่วงต้นซีซั่นเป็นตอนสั้นๆ ที่หนูนาเรียนรู้กติกาของร้านและช่วยเจ้าของความทรงจำทีละคนกลับมารับขวดคืน ช่วงกลางหนูนาค้นพบขวดสีทองและเริ่มปะติดปะต่อว่ายายทวดเคยมีคนรักที่ออกเรือไปแล้วไม่กลับมา จุดพีคคือคืนพายุใหญ่ที่ทำให้ขวดในร้านแตกกระจาย ความทรงจำของทั้งหมู่บ้านลอยปะปนกันกลางสายฝน หนูนากับเพื่อนๆ ต้องช่วยกันตามเก็บคืนก่อนรุ่งสาง ตอนจบซีซั่นหนูนาเปิดขวดสีทองให้ยายทวดในเช้าวันหนึ่งริมทะเล และแม้ยายทวดจะจำอะไรไม่ได้ทั้งหมด แต่รอยยิ้มของท่านบอกว่าความรู้สึกไม่เคยหายไปไหน พร้อมทิ้งปริศนาขวดสีเงินใบใหม่ที่ถูกคลื่นซัดมาเกยฝั่ง",
