    "logline": "หลังตู้เย็นของหอพักเก่ามีหมู่บ้านลับของภูตจิบิตัวป้อมห้าตนที่หากินกับของหายในห้อง เมื่อพี่เมย์เจ้าของห้องเกือบจับได้ สงครามซ่อนแอบสุดป่วนจังหวะรัวจึงเริ่มต้นขึ้นทุกตอน",
    "mainPlot": "ในหอพักเก่าย่านมหาวิทยาลัย มีสิ่งที่ผู้เช่าไม่มีวันรู้ นั่นคือหมู่บ้านจิ๋วของภูตจิบิห้าตนที่ซ่อนอยู่หลังตู้เย็นห้อง 204 พวกมันดำรงชีวิตด้วยการหยิบยืมของกระจุกกระจิกในห้อง ทั้งยางลบ กิ๊บติดผม และเศษขนมที่ตกพื้นไม่เกินห้าวินาที ภายใต้กฎเหล็กข้อเดียวคือห้ามให้มนุษย์เห็นตัวเด็ดขาด แต่ปัญหาคือพี่เมย์ นักศึกษาปีสามเจ้าของห้องเป็นคนช่างสังเกตระดับนักสืบ และเริ่มปักใจเชื่อว่าห้องตัวเองมีอะไรแปลกๆ ทุกตอนคือภารกิจสั้นกระชับของแก๊งจิบิ ตั้งแต่การขนคุกกี้ชิ้นเท่าตึกข้ามห้อง ปฏิบัติการช่วยหัวหน้าที่ติดอยู่ในกล่องทิชชู่ ไปจนถึงศึกแย่งชิงรีโมตแอร์กับแมวข้างห้อง ความฮาอยู่ที่แผนการยิ่งใหญ่อลังการของพวกมันมักพังด้วยเรื่องจิ๊บจ๊อยสุดๆ เสมอ แต่ไม่ว่าจะพังแค่ไหน แก๊งจิบิก็ยังรักห้อง 204 และแอบช่วยพี่เมย์ในวันที่เธอเหนื่อยโดยไม่ให้รู้ตัว",
    "seasonArc": "ช่วงต้นซีซั่นเป็นมุกรายตอนแนะนำนิสัยสุดเพี้ยนของจิบิแต่ละตัวผ่านภารกิจป่วนๆ ในห้อง ช่วงกลางพี่เมย์เริ่มวางกับดักจริงจัง ทั้งกล้องวงจรปิดจิ๋วและแป้งโรยพื้น ทำให้แก๊งต้องยกระดับแผนหลบหนีจนเกิดมหกรรมความวุ่นวายลามไปทั้งชั้นสอง จุดพีคคือวันที่หอพักประกาศรมยากำจัดแมลงทั้งตึก แก๊งจิบิต้องอพยพหมู่บ้านทั้งหมดภายในหนึ่งคืนโดยมีแมวข้างห้องขวางทุกเส้นทาง ตอนจบซีซั่นพวกมันย้ายกลับเข้าห้องสำเร็จ แต่ตัวจิ๋วที่ซุ่มซ่ามที่สุดดันทำหมวกใบเก่งหล่นไว้กลางโต๊ะอ่านหนังสือ และพี่เมย์กำลังถือมันขึ้นมาดูพร้อมรอยยิ้มปริศนา",
