    "mainPlot": "ปิดเทอมใหญ่ปีนี้ เจได เด็กชายจอมทฤษฎีสมคบคิด กับ จินนี่ พี่สาวสายลุยผู้ไม่เชื่ออะไรง่ายๆ ถูกพ่อแม่ส่งมาอยู่กับป้าทวดทองดีเจ้าของร้านชำเก่าแก่ประจำเมืองหนองแสง เมืองเล็กๆ ที่ดูน่าเบื่อสุดขั้ว จนกระทั่งเจไดพบว่าทุกวันพุธชั้นวางสินค้าแถวในสุดจะมีของแปลกโผล่มาขาย ทั้งปลากระป๋องที่ร้องเพลงได้ ยาสระผมที่ทำให้พูดภาษานกได้ และแผนที่เมืองที่มีถนนซึ่งไม่มีอยู่จริง สองพี่น้องเริ่มสืบว่าของพวกนี้มาจากไหน และพบว่าใต้ร้านชำมีประตูส่งของเชื่อมกับตลาดของสิ่งลี้ลับที่ป้าทองดีเป็นคู่ค้ามานานสี่สิบปี ยิ่งสืบก็ยิ่งเจอว่าชาวเมืองครึ่งหนึ่งไม่ใช่คนธรรมดา และมีองค์กรลึกลับชื่อชมรมแม่บ้านวันพฤหัสคอยจับตาร้านชำอยู่ ทุกตอนคือคดีป่วนหนึ่งเรื่องจากสินค้าหนึ่งชิ้น ที่ค่อยๆ ต่อจิ๊กซอว์ปริศนาใหญ่ของเมืองหนองแสง",
