    "logline": "ในหมู่บ้านเล็กๆ ที่ทุกอย่างปั้นจากดินน้ำมันสีพาสเทล ลูกหมีจอมเลอะเทอะกับผองเพื่อนช่วยกันแก้ปัญหาน่ารักๆ ประจำวัน ที่ทุกครั้งจะจบด้วยการค้นพบว่าการช่วยกันคนละมือทำให้ทุกอย่างกลมขึ้นเสมอ",
    "mainPlot": "หมู่บ้านขนมปั้นคือหมู่บ้านเล็กๆ บนเนินเขาสีครีม ที่บ้านทุกหลังมีรูปทรงเหมือนขนม ต้นไม้ปั้นเป็นก้อนกลมนุ่ม และเมฆบนฟ้าจับต้องได้เหมือนสำลี น้องมอมแมม ลูกหมีสีน้ำผึ้งผู้ทำอะไรก็เลอะเทอะไปหมด อาศัยอยู่กับเพื่อนรัก ทั้งกระต่ายขี้ตกใจ เป็ดน้อยช่างฝัน เต่าผู้ใจเย็นที่สุดในหมู่บ้าน และคุณยายแกะเจ้าของเตาอบกลางหมู่บ้าน ทุกตอนคือเรื่องราวอ่อนโยนหนึ่งเรื่อง เช่น วันที่เมฆฝนน้อยเศร้าจนไม่ยอมโปรยฝน วันที่สะพานข้ามลำธารหักแล้วทุกคนต้องช่วยกันปั้นใหม่ หรือวันที่มอมแมมอบเค้กวันเกิดให้เพื่อนแล้วเละไม่เป็นท่า ปัญหาทุกอย่างในหมู่บ้านไม่มีผู้ร้าย มีแต่ความเข้าใจผิดเล็กๆ ความกลัวนิดๆ และความไม่ตั้งใจหน่อยๆ ที่คลี่คลายได้ด้วยการรับฟัง ขอโทษ และช่วยกันปั้นแก้ไปด้วยกัน โดยมีเสน่ห์พิเศษคือเมื่อใจของทุกคนกลับมาอุ่น ดินน้ำมันรอบตัวจะเปลี่ยนเป็นสีสดใสขึ้นทั้งฉาก",
