    "visualBible": "แอนิเมชันสไตล์คอมิกบุ๊กเคลื่อนไหวแบบ Spider-Verse เฟรมภาพแบ่งเป็นแผงช่องคอมิกที่ขยับและแตกช่องได้ระหว่างฉากแอ็กชัน พื้นผิวพิมพ์แบบ halftone เม็ดสกรีนชัดเจนบนเงาและแก้มตัวละคร เส้นตัวละครเป็นลายเส้นหมึก ink คมหนาน้ำหนักสะบัดแบบปากกาคอแร้ง มี hatching เส้นแรเงาไขว้ในเงามืด สีพิมพ์เหลื่อม chromatic aberration ขอบแดงน้ำเงินหลุดทะเบียนแบบการ์ตูนพิมพ์เก่าเมื่ออารมณ์พุ่ง พาเลตหลักคือดำหมึก ขาวกระดาษ เหลืองมัสตาร์ด และฟ้าไซแอน โดยหมึกวิเศษของแทนเป็นดำเงาเหลือบรุ้งที่ไหลเป็นของเหลวตลอดเวลา ตัวหนังสือเอฟเฟกต์เสียงระเบิดเข้าเฟรมเป็นกราฟิกจริง กรอบคำบรรยายและบับเบิลความคิดโผล่ร่วมฉากได้ การเคลื่อนไหวเล่นเฟรมเรตคู่ ตัวเอกขยับ 12 เฟรมแบบกระชับมีจังหวะ ส่วนยางลบเคลื่อนไหวลื่นผิดธรรมชาติจนน่าขนลุก ฉากวาดสดใช้เส้นสเก็ตช์ดินสอโครงร่างปรากฏก่อนแล้วหมึกจึงวิ่งทับเป็นของจริง กล้องซูมกระแทกเข้าช่องคอมิกแทนการตัดฉากธรรมดา"
