    "mainPlot": "ไอเดีย นักออกแบบกราฟิกสาวผู้ตั้งคำถามกับทุกอย่างจนโดนเพื่อนร่วมงานเอือม คืนหนึ่งขณะปั่นงานอินโฟกราฟิกส่งลูกค้า เธอถูกดูดผ่านหน้าจอเข้าไปในดาต้าเวิร์ส โลกกว้างที่แนวคิดทุกเรื่องของมนุษย์เป็นเมืองจริงจับต้องได้ เมืองดอกเบี้ยทบต้นเป็นบันไดวนสูงเสียดฟ้า เมืองห่วงโซ่อาหารเป็นสวนสนุกหมุนเวียน และเมืองความน่าจะเป็นเป็นบ่อนคาสิโนยักษ์ที่แจกแต้มเป็นเปอร์เซ็นต์ เธอพบบ็อบบิน หุ่นเคอร์เซอร์จิ๋วผู้ทำหน้าที่การ์เดียนนำทาง และรู้ว่าดาต้าเวิร์สกำลังถูกหมอกข้อมูลปลอมชื่อสแปมม็อกกัดกินจนเมืองต่างๆ บิดเบี้ยว สะพานตรรกะขาด กราฟโค้งงอผิดรูป ไอเดียคือมนุษย์คนแรกในรอบร้อยปีที่เข้ามาได้ เพราะพลังของเธอคือคำถามที่ว่า ทำไม ซึ่งเป็นสิ่งเดียวที่สลายหมอกได้ ทั้งคู่จึงออกเดินทางซ่อมเมืองแนวคิดทีละเมือง โดยแต่ละตอนผู้ชมจะเข้าใจหนึ่งแนวคิดไปพร้อมตัวละครแบบไม่รู้ตัว",
    "seasonArc": "ช่วงต้นซีซั่นไอเดียเรียนรู้กติกาของดาต้าเวิร์สและซ่อมเมืองแนวคิดพื้นฐานอย่างเมืองเปอร์เซ็นต์และเมืองค่าเฉลี่ยที่บิดเบี้ยวเพราะข้อมูลปลอมง่ายๆ ช่วงกลางเมืองที่ซับซ้อนขึ้นอย่างเมืองอคติยืนยันและเมืองสหสัมพันธ์ลวงเริ่มเผยว่าสแปมม็อกไม่ได้เกิดเอง แต่มีผู้ปล่อยคือเดอะเฮดไลน์ อดีตการ์เดียนที่เชื่อว่าคนชอบเรื่องเร้าใจมากกว่าเรื่องจริง จุดพีคคือเมืองหลวงแห่งความจริงถูกหมอกกลืนทั้งเมืองจนกราฟทุกเส้นในดาต้าเวิร์สพังพร้อมกัน ตอนจบซีซั่นไอเดียไม่ได้ชนะด้วยการลบเดอะเฮดไลน์ทิ้ง แต่ด้วยการออกแบบเมืองใหม่ที่ทำให้ความจริงสนุกกว่าข่าวปลอมเป็นครั้งแรก ก่อนพบประตูมิติที่มีโลโก้บริษัทของเธอเองประทับอยู่",
