    "visualBible": "งาน 2.5D motion graphic ผสมสื่อสไตล์สตูดิโอออกแบบยุคใหม่ ตัวละครและเมืองเป็น flat design รูปทรงเรขาคณิตเรียบคม แต่จัดวางเป็นเลเยอร์ลึกหลายชั้นที่เคลื่อนด้วย parallax ต่างความเร็ว ให้มิติลอยตัวเหมือนไดโอรามากระดาษดิจิทัล พาเลตสีสไตล์อินโฟกราฟิกพรีเมียม น้ำเงินมิดไนต์เป็นฐาน ตัดด้วยส้มคอรัล เหลืองมะนาว มินต์ และชมพูช็อกกิ้งแบบเลือกใช้ทีละสองสามสีต่อเมือง พื้นผิวแฟลตแต่แต้ม grain กระดาษบางๆ และเงา drop shadow นุ่มชั้นเดียว องค์ประกอบข้อมูลคือฉากจริง กราฟแท่งเป็นตึก เส้น timeline เป็นถนน pie chart เป็นชิงช้าสวรรค์ ตัวเลขและ label ลอยประกอบฉากแบบ kinetic typography ที่เด้งเข้าออกตามจังหวะเสียง การเคลื่อนไหวคมเป๊ะตามหลัก motion design ใช้ easing หนึบ ตัด match-cut เปลี่ยนฉากด้วยรูปทรงที่แปลงร่างต่อเนื่อง วงกลมกลายเป็นล้อ กลายเป็นกราฟวงกลม กลายเป็นดวงอาทิตย์ กล้องเคลื่อนที่ในแกนลึกทะลุเลเยอร์เพื่อเข้าเมืองใหม่ หมอกข้อมูลปลอมเป็น glitch พิกเซลแตกสีจัดที่ตัดกับความเรียบคมของโลกปกติอย่างจงใจ"
