    "logline": "เด็กชายป.5 ได้แท็บเล็ตเก่าที่มี AI ผู้ช่วยจอมกวนชื่อไบต์ติดมาด้วย ทุกตอนคือหนึ่งภารกิจป่วนๆ ในโรงเรียนที่สอนให้เด็กเข้าใจว่า AI คืออะไร เก่งตรงไหน พลาดตรงไหน และใช้ยังไงให้ปลอดภัย",
    "mainPlot": "ปันปัน เด็กชายชั้นป.5 ขี้สงสัยแต่ขี้เกียจอ่านหนังสือ ได้แท็บเล็ตมือสองจากน้าที่ทำงานสายเทค ข้างในมี AI ผู้ช่วยชื่อไบต์ที่พูดเก่ง ตอบได้ทุกเรื่อง แต่บางทีก็ตอบผิดหน้าตาย ทุกตอนปันปันจะเจอปัญหาหนึ่งเรื่องในชีวิตเด็กๆ เช่น ทำการบ้าน แข่งวาดรูป หาของหาย หรือโดนเพื่อนแกล้ง แล้วพยายามใช้ไบต์ช่วย ก่อนจะได้เรียนรู้ความจริงหนึ่งข้อเกี่ยวกับ AI เช่น AI เรียนรู้จากข้อมูลจำนวนมากเลยเก่งเรื่องที่มีตัวอย่างเยอะ AI เดาคำตอบได้แต่ไม่รู้จริงเลยต้องตรวจสอบ ห้ามบอกชื่อจริง ที่อยู่ หรือรูปส่วนตัวกับแอปแปลกๆ และภาพที่เห็นในเน็ตอาจถูกสร้างขึ้นทั้งรูป เสน่ห์ของเรื่องอยู่ที่มุกโต้กันระหว่างเด็กจอมป่วนกับ AI จอมกวนที่ค่อยๆ กลายเป็นเพื่อนรักกัน ขณะที่ครูโอมครูคอมพิวเตอร์คอยเป็นกรรมการเฉลยว่าอะไรจริงอะไรมั่ว และย้ำกติกาทองว่าเรื่องสำคัญต้องถามผู้ใหญ่เสมอ",
    "seasonArc": "ช่วงต้นซีซั่นปูพื้นว่า AI คืออะไรและทำงานยังไงผ่านภารกิจสนุกๆ เช่น สอนไบต์ให้จำหน้าแมวข้างบ้าน จนเข้าใจเรื่องการเรียนรู้จากข้อมูลและอคติจากตัวอย่างที่ไม่ครบ ช่วงกลางเข้มขึ้นเป็นเรื่องการใช้อย่างถูกวิธี ทั้งการใช้ AI ช่วยการบ้านแบบไหนเรียกว่าเรียนรู้และแบบไหนเรียกว่าโกง การแยกภาพจริงกับภาพที่ AI สร้าง และบทเรียนครั้งใหญ่เมื่อปันปันเผลอกรอกข้อมูลส่วนตัวลงแอปปลอมจนเกือบเดือดร้อนทั้งบ้าน ช่วงพีคมีคนใช้ภาพตัดต่อแกล้งเพื่อนร่วมห้องจนเพื่อนไม่กล้ามาโรงเรียน ปันปันต้องรวบรวมทุกความรู้ที่สะสมมาทั้งซีซั่นเพื่อพิสูจน์ความจริงร่วมกับครูและผู้ปกครองอย่างถูกวิธี ตอนจบปันปันกับไบต์เปิดชมรมรู้ทัน AI สอนกติกาการใช้ให้เพื่อนทั้งห้อง พร้อมทิ้งปมว่าน้าผู้ให้แท็บเล็ตกำลังจะพาไบต์เวอร์ชันใหม่มาให้ลอง",
