    "mainPlot": "ครูตั้ม ครูฟิสิกส์หนุ่มโรงเรียนประจำอำเภอ กำลังจะเสียคาบสอนให้วิชาอื่นเพราะเด็กสอบตกยกห้องและไม่มีใครเห็นว่าฟิสิกส์เกี่ยวอะไรกับชีวิต โจ๊กนักเรียนหลังห้องที่ซ่อมมอเตอร์ไซค์เก่งกว่าทำข้อสอบท้าครูกลางห้องว่าถ้าฟิสิกส์แน่จริงให้เอามาใช้ที่อู่ของลุงหนวดให้ดูหน่อย ครูตั้มรับคำท้าแล้วพบว่านั่นคือการสอนที่ดีที่สุดในชีวิต แต่ละตอนเขาจะหยิบสถานการณ์จริงหนึ่งเรื่องมาสอนหนึ่งหลักการ เช่น สอนทีมวอลเลย์บอลของเฟิร์นรับลูกตบให้เจ็บน้อยลงด้วยการถอยมือตามลูกเพื่อยืดเวลาปะทะให้แรงกระแทกลดลง อธิบายว่าทำไมรถเบรกบนถนนเปียกต้องเผื่อระยะมากขึ้นเรื่องแรงเสียดทาน ใช้คานงัดกับรอกช่วยลุงหนวดยกเครื่องยนต์ที่หนักเกินแรงคน และสอนเรื่องไฟฟ้าลัดวงจรหลังบ้านป้าข้างอู่เกือบไฟไหม้ ปมของเรื่องคือครูตั้มต้องพิสูจน์ผลลัพธ์ให้ทันก่อนโรงเรียนตัดสินอนาคตวิชาของเขา ขณะที่โจ๊กค่อยๆ เปลี่ยนจากเด็กที่ถูกตราหน้าว่าโง่ เป็นคนที่เข้าใจฟิสิกส์ลึกที่สุดในห้องเพราะมือเขาสัมผัสมันมาตลอด",
    "seasonArc": "ช่วงต้นซีซั่นเป็นกลศาสตร์ผ่านสนามกีฬา ทั้งแรง โมเมนตัม จุดศูนย์ถ่วง และการเคลื่อนที่แบบโพรเจกไทล์ของลูกเสิร์ฟ ทีมวอลเลย์บอลเริ่มชนะและเด็กเริ่มหันมาฟังครูตั้ม ช่วงกลางย้ายไปอู่และบ้านเรือน สอนเรื่องคาน รอก ความดัน ความร้อน และไฟฟ้าในบ้านที่พลาดแล้วถึงชีวิต พร้อมปมที่โรงเรียนสั่งประเมินวิชาของครูตั้มจากคะแนนสอบกลางภาคที่กำลังจะมาถึง ช่วงพีคในงานกีฬาสีประจำปี ครูตั้มสังเกตเห็นนั่งร้านเวทีและป้ายโฆษณาขนาดใหญ่ติดตั้งผิดหลักจนใกล้ถล่มขณะคนแน่นสนาม เขากับโจ๊กและเฟิร์นต้องใช้ความรู้ทั้งซีซั่น ทั้งจุดศูนย์ถ่วง แรงลม และการกระจายน้ำหนัก ป้องกันโศกนาฏกรรมต่อหน้าทั้งอำเภอ ตอนจบวิชาฟิสิกส์กลายเป็นคาบที่เด็กแย่งกันลง โจ๊กตั้งเป้าสอบเข้าสายอาชีพวิศวกรรม และครูตั้มได้รับจดหมายเชิญไปทำโครงการห้องเรียนชุมชนที่ใหญ่กว่าเดิม",
