    "title": "น้ำหวานประจำซอย รู้ไว้ไม่โดนโกง",
    "category": "everyday-general-knowledge",
    "logline": "อดีตพนักงานธนาคารกลับบ้านมาเปิดร้านกาแฟเล็กๆ แต่กลายเป็นที่พึ่งของทั้งซอยโดยไม่ตั้งใจ ทุกตอนคือหนึ่งเรื่องใกล้ตัวที่คนไทยควรรู้ ตั้งแต่แก๊งคอลเซ็นเตอร์ ดอกเบี้ย สัญญา ไปจนถึงสิทธิรักษาพยาบาลของตัวเอง",
    "mainPlot": "น้ำหวาน อดีตพนักงานสินเชื่อธนาคารที่ลาออกมาดูแลยายบุญมีที่บ้านต่างจังหวัด เปิดร้านกาแฟหน้าบ้านตั้งใจใช้ชีวิตเงียบๆ แต่วันแรกที่เปิดร้านก็ต้องคว้าโทรศัพท์จากมือยายที่กำลังจะโอนเงินให้แก๊งคอลเซ็นเตอร์ที่อ้างเป็นตำรวจ ข่าวเรื่องหลานสาวคนเก่งช่วยยายไว้ได้แพร่ทั่วซอยภายในวันเดียว จากนั้นร้านกาแฟก็กลายเป็นศูนย์ปรึกษาประจำหมู่บ้านโดยปริยาย แต่ละตอนจะมีชาวบ้านหนึ่งคนหอบปัญหามาหนึ่งเรื่อง เช่น เจ๊หมวยโดนทวงหนี้นอกระบบดอกเบี้ยโหดเกินกฎหมาย ลุงข้างบ้านจะเซ็นค้ำประกันให้คนรู้จักโดยไม่อ่านสัญญา ป้าอีกคนไม่กล้าไปหาหมอเพราะคิดว่าบัตรทองรักษาไม่ได้จริง หรือแม่ค้าออนไลน์มือใหม่ตกใจเรื่องภาษีขายของ น้ำหวานจะคลี่ปัญหาให้เห็นกลไกทีละขั้น สรุปเป็นข้อควรรู้ที่จำง่าย และพาไปหาหน่วยงานที่ถูกต้องเมื่อเกินมือ เสน่ห์ของเรื่องคือความแซ่บของชีวิตในซอยที่ทั้งขำทั้งจริง กับสารวัตรเข้มตำรวจหนุ่มที่แวะมากินกาแฟบ่อยผิดสังเกต",
