    "mainPlot": "จ่าสิบเอกภูวดล ครูฝึกหน่วยรบพิเศษที่ขอย้ายตัวเองมาเป็นครูฝึกทหารใหม่ที่กรมทหารราบชายแดนอีสานหลังภารกิจลาดตระเวนที่ทำให้ จ่าเดช เพื่อนรักตายในเหตุปะทะที่รายงานราชการระบุว่าเป็น 'ความผิดพลาดทางยุทธวิธี' แต่ละตอนเล่าชีวิตจริงในกรม ตั้งแต่การฝึกทหารเกณฑ์ผลัดใหม่ที่มีทั้งเด็กบ้านรวยหนีหมายเรียกไม่พ้น เด็กกำพร้าที่สมัครเพราะอยากมีข้าวกิน ไปจนถึงภารกิจช่วยน้ำท่วม ลาดตระเวนแนวชายแดน และการปะทะกับขบวนการของเถื่อนที่ใช้เส้นทางป่ารอยต่อ ภูวดลค่อยๆ ผูกพันกับทหารใหม่เหมือนน้องชาย โดยเฉพาะพลทหารกล้า ลูกชายของจ่าเดชที่สมัครเข้ากรมเดียวกันเพื่อตามหาความจริงเรื่องพ่อ ยิ่งใกล้ชิดกันเท่าไหร่ ภูวดลยิ่งถูกบีบจากผู้พันธนากร นายทหารผู้เขียนรายงานฉบับนั้น ให้เก็บเรื่องในคืนปะทะไว้ตลอดไป เพราะความจริงคือคืนนั้นหน่วยของพวกเขาถูกส่งไปเป็นเครื่องมือเคลียร์เส้นทางให้ธุรกิจมืดของนายทหารบางคน",
    "seasonArc": "ช่วงต้นซีซั่นเน้นชีวิตครูฝึกกับทหารเกณฑ์ผลัดใหม่ ความโหดของการฝึกที่ซ่อนความห่วงใย และมิตรภาพที่ค่อยๆ ก่อตัวในกองร้อย ช่วงกลางภารกิจชายแดนเริ่มถี่ขึ้นและพลทหารกล้าเริ่มขุดคุ้ยแฟ้มภารกิจของพ่อ ทำให้ภูวดลต้องเลือกระหว่างปกป้องเด็กหนุ่มหรือปกป้องความลับ จุดพีคคือภารกิจลาดตระเวนที่ประวัติศาสตร์ซ้ำรอย หน่วยถูกส่งเข้าพื้นที่เดิมด้วยคำสั่งที่ผิดปกติแบบเดียวกับคืนที่จ่าเดชตาย ภูวดลขัดคำสั่งเพื่อพาลูกหน่วยทั้งหมดกลับมาครบ ตอนจบซีซั่นเขายอมขึ้นให้การต่อคณะกรรมการสอบสวน เปิดโปงรายงานเท็จโดยรู้ดีว่าอาจต้องแลกด้วยชีวิตราชการทั้งหมดของตัวเอง ก่อนจบด้วยคำสั่งย้ายปริศนาที่ส่งเขาไปหน่วยที่อันตรายที่สุดของประเทศ",
