    "logline": "แพทย์ใช้ทุนหญิงมือหนึ่งของรุ่นเลือกกลับมาอยู่โรงพยาบาลชุมชนบ้านเกิดแทนที่จะไปต่อเฉพาะทางในเมือง เพื่อค้นหาความจริงว่าทำไมแม่ของเธอถึงเสียชีวิตบนเตียงของโรงพยาบาลแห่งนี้เมื่อสิบปีก่อน ทั้งที่เวชระเบียนคืนนั้นหายไปทั้งแฟ้ม",
    "mainPlot": "หมอพราว แพทย์ใช้ทุนปีสองที่ขอย้ายมาโรงพยาบาลชุมชนเวียงคำ อำเภอบ้านเกิดที่มีหมอประจำเพียงสี่คนแต่ผู้ป่วยล้นทุกวัน แต่ละตอนคือเคสที่หมอต่างจังหวัดเจอจริง ตั้งแต่ผู้ป่วยหัวใจขาดเลือดที่ต้องตัดสินใจให้ยาละลายลิ่มเลือดเองเพราะส่งตัวไม่ทัน อุบัติเหตุหมู่ช่วงสงกรานต์ คนไข้เบาหวานที่ไม่มีเงินค่ารถมาตามนัด ไปจนถึงการตัดสินใจปลายทางชีวิตของผู้ป่วยติดเตียงที่ครอบครัวเห็นไม่ตรงกัน พราวต้องเรียนรู้ว่าการแพทย์ในโลกจริงไม่ใช่แค่วินิจฉัยถูก แต่คือการบริหารทรัพยากรที่ไม่เคยพอ เวรที่ติดกันสามสิบชั่วโมง และจริยธรรมที่ไม่มีในตำรา ขณะเดียวกันเธอค่อยๆ สืบเรื่องการตายของแม่ที่เสียชีวิตหลังผ่าตัดไส้ติ่งธรรมดาในคืนที่โรงพยาบาลรับผู้ป่วยเกินกำลัง และพบว่าหมอเวรคืนนั้นคือ นพ.ประวิทย์ ผู้อำนวยการคนปัจจุบันที่ทั้งอำเภอเคารพ และคือคนที่กำลังผลักดันให้เธอได้ทุนเรียนต่อเฉพาะทางอย่างผิดสังเกต",
    "seasonArc": "ช่วงต้นซีซั่นพราวปรับตัวกับความจริงของโรงพยาบาลชุมชน จากหมอมือหนึ่งที่มั่นใจเกินร้อยสู่หมอที่ต้องยอมรับว่าตัวเองช่วยทุกคนไม่ได้ ช่วงกลางเธอเริ่มเป็นที่รักของคนไข้และทีมพยาบาล พร้อมกับขุดพบว่าเวชระเบียนของแม่ไม่ได้หายแต่ถูกทำให้หาย และมีพยาบาลเก่าอีกคนที่ลาออกกะทันหันหลังคืนนั้น จุดพีคคือเมื่อโรงพยาบาลเผชิญเหตุอุบัติเหตุหมู่ครั้งใหญ่และ นพ.ประวิทย์ ลงมือช่วยชีวิตคนไข้เคียงบ่าเคียงไหล่กับเธอทั้งคืน ทำให้พราวสับสนว่าคนที่เธอตามล่าความจริงคือหมอที่เลวหรือหมอที่เคยพลาด ตอนจบซีซั่นความจริงเปิดเผยว่าคืนนั้นแม่ของเธอเสียชีวิตเพราะระบบที่ล้มเหลว หมอหนึ่งคนต่อคนไข้ทั้งอำเภอ และการปกปิดเกิดขึ้นเพื่อปกป้องโรงพยาบาลไม่ให้ถูกปิด พราวต้องเลือกว่าจะเปิดโปงเพื่อความยุติธรรมของแม่ หรือรักษาโรงพยาบาลเดียวที่คนอำเภอนี้มีไว้พึ่งพิง",
