    "mainPlot": "มิ้นต์ อดีตพนักงานการตลาดวัยยี่สิบเก้าที่ถูกเลย์ออฟกะทันหันขณะแบกหนี้บัตรเครดิตและค่ารักษาพ่อ เธอกำเงินก้อนสุดท้ายไปเหมาเสื้อผ้าโรงเกลือมาเปิดไลฟ์ขายในห้องเช่า คืนแรกมีคนดูสามคนซึ่งหนึ่งในนั้นคือแม่ตัวเอง แต่ละตอนเล่าการสู้ชีวิตแม่ค้าออนไลน์อย่างสมจริง ตั้งแต่การหาของ ถ่ายรูป เขียนแคปชัน วิ่งส่งพัสดุให้ทันรอบตัดยอด รับมือลูกค้าเทของเก็บเงินปลายทาง รีวิวปลอม และดราม่าทัวร์ลงจากคลิปที่ถูกตัดต่อ มิ้นต์ค่อยๆ ปั้นตัวตน 'มิ้นต์ปากตลาด' แม่ค้าไลฟ์ปากไวใจถึงจนยอดผู้ชมพุ่ง พร้อมได้แก๊งค์เพื่อนร่วมทาง ทั้งไอซ์ รูมเมทที่กลายมาเป็นแอดมิน และเจ๊หงส์ เจ้าแม่ค้าส่งโรงเกลือผู้สอนวิชาดูผ้าดูของ แต่ยิ่งดังยิ่งมีศัตรู เมื่อ 'เจ๊เพชร' แม่ค้าไลฟ์เบอร์หนึ่งของวงการเริ่มมองมิ้นต์เป็นเสี้ยนหนาม ทั้งตัดราคา ปล่อยข่าว และซื้อตัวคนใกล้ชิด จนมิ้นต์พบว่าออเดอร์ล็อตใหญ่ที่สุดในชีวิตเธออาจเป็นกับดักที่ออกแบบมาให้เธอล้มทั้งกระดาน",
