    "mainPlot": "ปกรณ์ วิศวกรโยธาวัยสามสิบสองจากครอบครัวช่างก่อสร้าง ผู้ไต่จากวิศวกรสนามจนได้เป็นผู้จัดการโครงการคอนโดสามสิบชั้นของบริษัทรับเหมายักษ์ใหญ่ แต่ละตอนเล่าโลกไซต์ก่อสร้างอย่างคนในวงการ ตั้งแต่การคุมงานเทคอนกรีตที่พลาดไม่ได้แม้นาทีเดียว การตรวจรับเหล็กเส้น ปัญหาแรงงานข้ามชาติไร้ใบอนุญาต อุบัติเหตุนั่งร้าน ไปจนถึงการเจรจากับผู้รับเหมาช่วงที่พร้อมลดสเปกทุกครั้งที่ถูกบีบราคา ปกรณ์เริ่มสังเกตความผิดปกติเมื่อผลทดสอบกำลังอัดคอนกรีตบางล็อตหายไปจากระบบ และเหล็กข้ออ้อยที่เข้าไซต์มีใบรับรองที่ดูใหม่เกินจริง เมื่อสาวลึกลงไปเขาพบขบวนการสวมเอกสารวัสดุที่ประหยัดต้นทุนหลายร้อยล้าน โดยมีลายเซ็นสามัญวิศวกรของ อาจารย์วสันต์ รุ่นพี่ผู้ปั้นเขามากับมือกำกับอยู่ทุกฉบับ ขณะเดียวกันบริษัทกำลังเร่งปิดงานให้ทันงานเปิดตัวขายต่างชาติ และแรงสั่นสะเทือนเล็กๆ ที่ชั้นใต้ดินเริ่มบอกปกรณ์ว่าเวลาของตึกนี้อาจน้อยกว่าที่ใครกล้ายอมรับ",
