    "mainPlot": "ฝ้าย นักการตลาดสาวที่เพิ่งถูกเลย์ออฟ จำใจกลับบ้านต่างจังหวัดมาช่วยดูแลร้านเครื่องมือช่างอายุกว่าสี่สิบปีของลุงเหล็ก ช่างรุ่นเก๋าปากร้ายใจดีที่ยึดคติว่าจะไม่ขายของห่วยให้ลูกค้าแม้จะกำไรดีแค่ไหน ร้านกำลังจะไปไม่รอดเพราะเมกะสโตร์เครื่องมือราคาถูกมาเปิดตรงข้ามพอดี ฝ้ายจึงเสนอไอเดียถ่ายคลิปสอนใช้เครื่องมือลงโซเชียล โดยให้ลุงเหล็กเป็นพระเอกจำเป็นที่สาธิตของจริงหน้างานจริง แต่ละตอนลูกค้าจะเดินเข้าร้านมาพร้อมปัญหาหนึ่งอย่าง เช่น สว่านไหม้เพราะใช้ดอกผิดประเภท ประแจปากตายรูดจนน็อตเสียหาย หรือซื้อเลื่อยวงเดือนถูกๆ มาแล้วเกือบเสียนิ้ว และลุงเหล็กจะสอนทั้งวิธีใช้ที่ถูกต้อง จุดปลอดภัยที่ห้ามละเลย และวิธีเลือกซื้อว่าเมื่อไหร่ควรจ่ายแพง เมื่อไหร่ของถูกก็เพียงพอ ความขัดแย้งเข้มข้นขึ้นเมื่อผู้จัดการเมกะสโตร์ใช้ทั้งสงครามราคาและรีวิวปลอมโจมตีร้าน ขณะที่ฝ้ายค่อยๆ ค้นพบว่าตัวเองรักงานช่างที่เคยหนีมาทั้งชีวิต และความลับว่าทำไมพ่อของเธอถึงตัดขาดจากลุงเหล็กเมื่อยี่สิบปีก่อนก็เริ่มถูกเปิดออกทีละชั้น",
    "seasonArc": "ช่วงต้นซีซั่นฝ้ายกับลุงเหล็กปะทะกันเรื่องวิธีทำร้าน ระหว่างที่คลิปสอนเครื่องมือพื้นฐานอย่างค้อน ไขควง ประแจ และสว่าน เริ่มมีคนดูและลูกค้าหน้าใหม่ทยอยเข้าร้าน ช่วงกลางร้านเริ่มมีชื่อเสียงจนเมกะสโตร์เปิดเกมสกปรก ทั้งตัดราคา จ้างรีวิวโจมตีว่าร้านขายของแพงเกินจริง และดึงตัวเปา ลูกมือที่ลุงเหล็กปั้นมากับมือไปด้วยเงินเดือนสูงลิ่ว ช่วงพีคเกิดอุบัติเหตุหน้างานจากเครื่องมือเกรดต่ำที่เมกะสโตร์ขายให้ผู้รับเหมารายหนึ่ง ทำให้คนงานบาดเจ็บสาหัส และหลักฐานทั้งหมดชี้ว่าลุงเหล็กเคยเตือนเรื่องนี้ไว้แล้วในคลิปที่ถูกกดรายงานจนหายไป ตอนจบซีซั่นความจริงถูกเปิดในเวทีงานแฟร์เครื่องมือประจำจังหวัด เมื่อเปากลับมายืนข้างลุงเหล็กพร้อมหลักฐานภายในของเมกะสโตร์ ร้านรอดมาได้ด้วยความไว้ใจของลูกค้าทั้งเมือง และฝ้ายตัดสินใจรับช่วงต่อร้านพร้อมปมใหม่ว่าพ่อของเธอกำลังเดินทางกลับมา",
