    "visualBible": "โทนภาพอบอุ่นสไตล์ร้านห้องแถวไม้เก่า ผนังแขวนเครื่องมือเรียงเป็นระเบียบจนเหมือนพิพิธภัณฑ์ แสงทังสเตนสีส้มตัดกับแสงนีออนขาวเย็นของเมกะสโตร์ฝั่งตรงข้าม โทนสีน้ำตาลไม้ เทาเหล็ก และส้มสนิม ทุกตอนมีอินเสิร์ตสอนงานชัดๆ ทั้งโคลสอัพมือจับเครื่องมือในองศาที่ถูกต้อง สโลว์โมชันจังหวะสว่านเจาะหรือเลื่อยตัด กราฟิกชื่ออุปกรณ์พร้อมราคาโดยประมาณ ตารางเทียบของถูกกับของคุ้ม และแถบเตือนความปลอดภัยสีเหลืองดำทุกครั้งที่มีขั้นตอนเสี่ยง เช่น ต้องใส่แว่นนิรภัยหรือถอดปลั๊กก่อนเปลี่ยนใบเลื่อย"
