    "mainPlot": "มิว สาวออฟฟิศวัยยี่สิบเก้า ตัดสินใจถอนเงินเก็บทั้งชีวิตซื้อบ้านเดี่ยวมือสองราคาถูกผิดสังเกต เพื่อพาแม่ที่ป่วยออกจากห้องเช่าแคบๆ ให้ได้ แต่คืนแรกที่ย้ายเข้าก็เจอครบทั้งหลังคารั่ว ก๊อกน้ำแตก และไฟดับครึ่งบ้าน เงินที่เหลือไม่พอจ้างช่างรีโนเวต เธอจึงต้องลงมือซ่อมเองทีละจุดโดยมีลุงสิงห์ เพื่อนบ้านปากหมาผู้เป็นอดีตช่างรับเหมาฝีมือดีที่สาบานเลิกจับเครื่องมือหลังความผิดพลาดในอดีต คอยตะโกนสอนข้ามรั้วอย่างเสียไม่ได้ แต่ละตอนโฟกัสงานซ่อมจริงหนึ่งเรื่อง ตั้งแต่เปลี่ยนก๊อกน้ำ แก้ส้วมตัน อุดรอยรั่วหลังคา โป๊วผนังทาสี ไปจนถึงงานไฟฟ้าเบื้องต้นอย่างเปลี่ยนหลอดไฟและเช็กเบรกเกอร์ ซึ่งลุงสิงห์จะขีดเส้นชัดเจนเสมอว่างานไหนมือใหม่ทำได้ และงานไหนอย่างการเดินสายไฟใหม่หรือแก้ตู้เมนไฟฟ้าต้องเรียกช่างมีใบรับรองเท่านั้นเพราะพลาดครั้งเดียวคือชีวิต เรื่องซับซ้อนขึ้นเมื่อมิวค้นพบว่าบ้านหลังนี้ถูกขายถูกเพราะเป็นบ้านที่ลุงสิงห์เคยสร้างให้ครอบครัวของตัวเองก่อนทุกอย่างจะพังทลาย และนายหน้าเจ้าเล่ห์ที่ขายบ้านให้เธอก็กำลังกว้านซื้อบ้านทั้งซอยเพื่อโครงการใหม่โดยหวังให้มิวถอดใจย้ายออกไปเอง",
    "seasonArc": "ช่วงต้นซีซั่นมิวลุยงานซ่อมเล็กที่เห็นผลไว ทั้งก๊อกน้ำ ส้วมตัน มุ้งลวด และสีผนัง สลับกับการง้อความรู้จากลุงสิงห์ที่ยังไม่ยอมเหยียบเข้ามาในบ้านหลังนี้แม้แต่ก้าวเดียว ช่วงกลางงานเริ่มยากขึ้นเป็นหลังคารั่ว ฝ้าบวม และปัญหาไฟฟ้าที่ทำให้มิวเกือบพลาดครั้งใหญ่จนลุงสิงห์ต้องยอมทำลายคำสาบานเข้ามาช่วยถึงที่ พร้อมเปิดใจเล่าอดีตว่าบ้านหลังนี้พังไม่ใช่เพราะฝีมือเขา แต่เพราะวัสดุที่หุ้นส่วนเก่าแอบสลับ ช่วงพีคนายหน้าเจ้าเล่ห์ฉวยเรื่องนี้ปล่อยข่าวว่าบ้านทั้งซอยโครงสร้างไม่ปลอดภัยเพื่อทุบราคากว้านซื้อ มิวกับลุงสิงห์จึงเปิดบ้านไลฟ์โชว์การตรวจสภาพจริงทีละจุดให้คนทั้งซอยดูว่าอะไรคือปัญหาจริง อะไรคือการปั่นราคา ตอนจบซีซั่นบ้านซ่อมเสร็จรับแม่เข้ามาอยู่ได้จริง ลุงสิงห์กลับมาจับเครื่องมืออย่างภาคภูมิ และทั้งซอยรวมตัวกันไม่ขายบ้าน แต่โน้ตสุดท้ายที่นายหน้าทิ้งไว้บอกว่าเกมของเขาเพิ่งเริ่มต้น",
