    "mainPlot": "กัน หนุ่มออฟฟิศวัยสามสิบผู้เบื่อเงินเดือน หมดเงินเก็บเกือบทั้งหมดให้คอร์ส 'รวยด้วยคอนโดไม่ใช้เงินตัวเอง' ของโค้ชเจฟ กูรูโซเชียลที่พาลูกศิษย์กู้ซื้อห้องเกินราคาจนกันติดหนี้ผ่อนห้องที่ปล่อยเช่าไม่ออก จุดเปลี่ยนมาถึงเมื่อเขาได้เจอป้าอร เจ้าของห้องเช่าสิบกว่าห้องที่สร้างพอร์ตมายี่สิบปีโดยไม่เคยออกสื่อ ป้าอรรับกันเป็นลูกมือแลกกับการสอนของจริงทีละบท ตั้งแต่การคำนวณผลตอบแทนค่าเช่าที่ต้องหักค่าส่วนกลาง ค่าซ่อม และเดือนที่ห้องว่างก่อนจะเรียกว่ากำไร การซื้อมาขายไปที่ต้องเจอทั้งภาษีธุรกิจเฉพาะเมื่อถือครองไม่ครบห้าปีและค่าใช้จ่ายรีโนเวตที่บานปลายเสมอ ไปจนถึงสนามประมูลบ้านจากกรมบังคับคดีที่ราคาถูกจริงแต่ต้องวางหลักประกันก่อนเคาะและเสี่ยงเจอผู้อยู่อาศัยเดิมไม่ยอมย้ายออก ยิ่งเรียนกันยิ่งเห็นว่าความรวยของโค้ชเจฟมาจากการขายคอร์ส ไม่ใช่จากค่าเช่า และลูกศิษย์รุ่นเดียวกับเขากำลังทยอยถูกยึดห้อง เรื่องราวเดินหน้าด้วยคำถามเดียวที่ซีรีส์ไม่เคยตอบแทนคนดู คือความเสี่ยงแค่ไหนที่เรารับไหวจริงๆ",
    "seasonArc": "ช่วงต้นซีซั่นเปิดด้วยความฝันลอยฟุ้งของกันในคอร์สสัมมนา ก่อนความจริงจะไล่ทุบทีละดอกเมื่อห้องปล่อยเช่าไม่ออกและงวดผ่อนไล่หลัง ช่วงกลางกันฝึกงานกับป้าอร เรียนรู้การดูทำเล คัดผู้เช่า ทำสัญญาเช่า และตามหนี้ค่าเช่าจากน้าแดงผู้เช่าเจ้าปัญหา พร้อมค่อยๆ กู้สถานะการเงินของตัวเองกลับมาแบบไม่มีทางลัด จุดพีคคือการเปิดโปงโค้ชเจฟเมื่อลูกศิษย์รุ่นเดียวกับกันรวมตัวฟ้องร้อง และกันต้องเลือกว่าจะเงียบเพื่อรักษาหน้า หรือยอมเปิดบัญชีขาดทุนของตัวเองต่อสาธารณะเพื่อเตือนคนอื่น ช่วงท้ายกันขายห้องแรกแบบยอมเจ็บเพื่อตัดขาดทุน แล้วเริ่มดีลที่สองด้วยเงินที่น้อยกว่าแต่ความรู้ที่มากกว่า ปิดซีซั่นด้วยกำไรก้อนแรกที่เล็กมากแต่เป็นของจริง",
