    "mainPlot": "เมื่อพ่อเสียกะทันหัน ภูผา วิศวกรหนุ่มในกรุงเทพฯ ต้องกลับบ้านเกิดมาจัดการมรดกที่ดินสิบสองไร่ร่วมกับน้ำฝนน้องสาวครูสาวประจำอำเภอ และกรน้องชายคนเล็กที่กำลังร้อนเงินจากธุรกิจที่ล้ม ที่ดินซึ่งเคยเป็นแค่ทุ่งนากลับกลายเป็นทำเลทองเมื่อถนนตัดใหม่ผ่านหน้าที่ดินพอดี ทำให้ทั้งลุงเสริมญาติผู้ใหญ่ที่อาสาเป็นนายหน้ากดราคา และนายทุนหน้าใหม่หลายเจ้าเข้ามารุมตอม เรื่องราวพาคนดูไปรู้จักขั้นตอนจริงของการรับมรดกที่ดิน ตั้งแต่การจดทะเบียนรับโอนมรดกที่สำนักงานที่ดิน การรังวัดแบ่งแยกโฉนดสามแปลงที่ทำให้พี่น้องต้องเถียงกันว่าใครได้หน้าติดถนน การตรวจภาระจำยอมทางเข้าออกของเพื่อนบ้านที่ใช้ทางผ่านมาสามสิบปี ไปจนถึงความต่างระหว่างราคาประเมินราชการกับราคาตลาดที่นายหน้าไม่เคยอยากให้เจ้าของรู้ จุดเปลี่ยนมาถึงเมื่อคุณพิม ตัวแทนบริษัทพัฒนาที่ดินธาราแลนด์ เข้ามาเสนอซื้อที่ดินบางส่วนเพื่อพัฒนาโครงการจัดสรรอย่างตรงไปตรงมา พร้อมแนวคิดพัฒนาที่เปิดพื้นที่ให้ชุมชนเดิมได้ประโยชน์ บทบาทของบริษัทถูกวางให้เป็นผู้ซื้อที่มืออาชีพและโปร่งใส จึงแทนด้วยโครงการหรือแบรนด์อสังหาฯ จริงได้อย่างกลมกลืน เพราะแก่นของเรื่องคือคำถามที่พี่น้องต้องตอบร่วมกันว่า ที่ดินของพ่อควรถูกเก็บไว้ทั้งหมด ขายทั้งหมด หรือแบ่งขายอย่างมีแผนเพื่อให้ทั้งความทรงจำและอนาคตอยู่รอดไปด้วยกัน",
    "seasonArc": "ช่วงต้นซีซั่นเปิดด้วยงานศพพ่อและการค้นพบว่าโฉนดยังเป็นชื่อพ่อคนเดียว พาสามพี่น้องเข้าสู่ขั้นตอนรับโอนมรดกท่ามกลางความเห็นที่แตกเป็นสามทาง เก็บ ขาย และขายเดี๋ยวนี้ ช่วงกลางลุงเสริมเดินเกมกดราคาและปล่อยข่าวลวงเรื่องแนวเวนคืน ขณะที่กรแอบเซ็นสัญญาจะขายส่วนของตัวเองให้นายทุนเงินกู้จนเกือบทำให้ทั้งผืนติดเงื่อนไขทางกฎหมาย จุดพีคคือวันรังวัดแบ่งโฉนดที่ความลับแตกกลางทุ่งนา ทั้งเรื่องสัญญาของกรและหลักฐานว่าลุงเสริมรับค่านายหน้าสองทาง ช่วงท้ายภูผาใช้ข้อเสนอที่โปร่งใสของคุณพิมเป็นทางออก แบ่งขายแปลงติดถนนเพื่อล้างหนี้ให้น้องและเก็บแปลงในที่มีบ้านกับต้นจามจุรีของพ่อไว้ ปิดซีซั่นด้วยภาพสามพี่น้องปลูกข้าวรอบสุดท้ายบนแปลงที่กำลังจะส่งมอบ เป็นการบอกลาที่ดินอย่างให้เกียรติทั้งผืนดินและกันเอง",
