    "mainPlot": "ไอซ์ พนักงานการตลาดวัยยี่สิบแปด ใช้ชีวิตสามปีบนรถเมล์และรถตู้วันละเกือบสี่ชั่วโมงจากบ้านชานเมืองเข้าออฟฟิศกลางเมือง จนวันที่ร่างกายประท้วงด้วยการหลับในที่ประชุมครั้งสำคัญ เธอจึงตัดสินใจครั้งใหญ่ที่สุดในชีวิต คือซื้อห้องสตูดิโอในโครงการสกายริมสเตชั่น คอนโดใกล้สถานีรถไฟฟ้าที่เดินถึงออฟฟิศได้ในสิบห้านาที การเป็นเจ้าของห้อง 2408 เปิดโลกใหม่ให้เธอทั้งเรื่องที่ไม่มีใครสอน อย่างค่าส่วนกลาง เงินกองทุนสะสม การประชุมใหญ่ลูกบ้านที่เดือดกว่าละคร และมารยาทการอยู่ร่วมตึกกับคนแปลกหน้าร้อยครอบครัว ไปจนถึงเรื่องที่เธอไม่ได้ตั้งใจหา อย่างมิตรภาพกับเจ๊มะลิเจ้าของร้านกับข้าวชั้นล่างผู้รู้ความลับทั้งตึก และภาคิน สถาปนิกหนุ่มห้องข้างๆ ที่เจอกันครั้งแรกด้วยการทะเลาะเรื่องเสียงเจาะผนัง เวลาที่ได้คืนมาวันละสี่ชั่วโมงค่อยๆ เปลี่ยนชีวิตไอซ์ จากคนที่เหนื่อยเกินกว่าจะฝัน เป็นคนที่มีแรงเรียนคอร์สออนไลน์ ออกกำลังกาย และเปิดใจให้ความรัก ตัวโครงการสกายริมสเตชั่นทำหน้าที่เป็นฉากหลังของชีวิตที่ดีขึ้นจากทำเลและส่วนกลางที่ถูกใช้จริง จึงปรับเป็นโครงการคอนโดจริงของผู้สนับสนุนได้อย่างแนบเนียน เพราะหัวใจของเรื่องคือคำถามว่า บ้านหลังแรกของคนเมืองซื้อความสุขได้จริงหรือแค่ย้ายที่เหนื่อย",
