    "mainPlot": "ตะวัน สถาปนิกหนุ่มไฟแรงจากบริษัทดังในกรุงเทพฯ กลับบ้านเกิดเมืองรองทางเหนือเพราะยายบัวล้มป่วย และพบว่าย่านตลาดเก่าริมน้ำที่เขาโตมากำลังสั่นสะเทือน เมื่อบริษัทเหนือฟ้าดีเวลลอปเม้นท์ประกาศแผนพัฒนาโครงการที่อยู่อาศัยและย่านการค้าใหม่ชานเมือง พร้อมข่าวลือว่าตลาดเก่าจะถูกไล่รื้อ กำนันศักดิ์นายทุนท้องถิ่นฉวยจังหวะปั่นราคากว้านซื้อบ้านเก่าจากชาวบ้านที่ตื่นตระหนก หวังฟันกำไรจากการขายต่อยกแปลง แต่เมื่อตะวันได้พบคุณเมธ ผู้บริหารโครงการตัวจริง เขากลับพบความจริงที่ต่างจากข่าวลือ คือบริษัทตั้งใจพัฒนาพื้นที่ใหม่ชานเมืองโดยไม่แตะย่านเก่า และกำลังหาสถาปนิกท้องถิ่นมาช่วยออกแบบให้โครงการใหม่เชื่อมกับเมืองเดิมอย่างเคารพกัน ตะวันรับงานนี้ท่ามกลางสายตาระแวงของคนในชุมชนที่มองว่าเขาขายตัวให้นายทุน เรื่องราวถักคำถามจริงของเมืองรองทั่วประเทศเข้ากับชีวิตตัวละคร ทั้งราคาที่ดินที่ขยับตามผังเมืองใหม่ การรีโนเวตบ้านไม้เก่าให้เป็นที่พักและร้านค้าโดยไม่ทำลายจิตวิญญาณเดิม และสิทธิ์ของชาวบ้านที่จะเลือกอนาคตของตัวเอง บทบาทของบริษัทพัฒนาถูกออกแบบให้เป็นผู้มาเติมเมือง ไม่ใช่ผู้มายึดเมือง จึงแทนด้วยโครงการหรือแบรนด์ผู้พัฒนาจริงได้อย่างเป็นธรรมชาติ โดยเรื่องยังยืนได้ด้วยหัวใจของมันเอง คือความรักระหว่างคนกับเมืองที่เลี้ยงเขามา",
    "seasonArc": "ช่วงต้นซีซั่นตะวันกลับบ้านมาเจอทั้งอาการป่วยของยายและข่าวลือไล่รื้อที่ทำให้ตลาดเก่าปั่นป่วน ชาวบ้านเริ่มทยอยขายบ้านให้กำนันศักดิ์ในราคาที่ต่ำกว่าความจริง ช่วงกลางตะวันรับงานออกแบบจากคุณเมธและถูกชุมชนตราหน้าว่าทรยศ ขณะที่เขาเดินสายรีโนเวตบ้านยายเป็นต้นแบบ พิสูจน์ว่าบ้านเก่าสร้างรายได้ใหม่ได้โดยไม่ต้องขายทิ้ง และครูฝนช่วยเปิดเวทีให้ชาวบ้านเห็นแผนจริงของโครงการเป็นครั้งแรก จุดพีคคือการเปิดโปงว่ากำนันศักดิ์คือต้นตอข่าวลือไล่รื้อ และสัญญาซื้อบ้านที่ชาวบ้านเซ็นไปมีเงื่อนไขเอาเปรียบซ่อนอยู่ นำไปสู่การรวมตัวทวงสิทธิ์ครั้งใหญ่ของทั้งย่าน ช่วงท้ายชุมชนกับโครงการจับมือกันฟื้นตลาดเก่าเป็นถนนสายวัฒนธรรมที่เชื่อมกับเมืองใหม่ ปิดซีซั่นด้วยงานเปิดตลาดริมน้ำโฉมใหม่ที่ยายบัวนั่งมองหลานชายอยู่หน้าบ้านไม้หลังเดิมซึ่งยังตั้งอยู่ที่เดิม",
