    "mainPlot": "พราว โปรแกรมเมอร์สาวที่เพิ่งหนีความล้มเหลวจากงานเก่า ย้ายเข้าคอนโดมือสองราคาถูกผิดสังเกตบนชั้น 13 ของตึกเก่ากลางเมือง คืนแรกแอปดูกล้องวงจรปิดส่วนกลางของนิติบุคคลก็เด้งแจ้งเตือนขึ้นมาเองตอนตีสาม พร้อมคลิปจากกล้องตัวที่ไม่มีอยู่ในระบบ เป็นภาพห้องนอนของเธอเองที่มีเงาคนผมยาวยืนนิ่งอยู่ปลายเตียง ยิ่งเธอพยายามลบแอปหรือแจ้งนิติ เรื่องยิ่งบานปลาย เพราะทุกคนในตึกทำเหมือนไม่เคยมีห้อง 1313 อยู่จริง พราวเริ่มไล่ดูคลิปย้อนหลังและพบว่าผู้เช่าคนก่อนหายตัวไปหลังได้รับคลิปแบบเดียวกันติดต่อกัน 13 คืน กติกาที่เธอค่อยๆ ถอดรหัสได้คือ ยิ่งเปิดดูคลิป เงานั้นยิ่งขยับเข้าใกล้กล้องขึ้นทีละคืน แต่ถ้าไม่ดูเลย เสียงเคาะจากฝ้าเพดานจะดังขึ้นเรื่อยๆ จนกว่าจะยอมเปิด เบื้องหลังความหลอนคือความลับของนิติบุคคลที่เคยปิดข่าวการตายของช่างติดกล้องซึ่งถูกทิ้งให้ตายในช่องฝ้าระหว่างชั้น เพื่อไม่ให้ราคาห้องตก ส่วนพราวเองก็ต้องเผชิญปมที่เธอหนีมา คือเธอเคยเมินข้อความขอความช่วยเหลือของเพื่อนร่วมงานจนเขาฆ่าตัวตาย เงาในคลิปจึงรู้วิธีลงโทษคนที่เลือกจะไม่มองดีที่สุด",
    "seasonArc": "ช่วงต้นซีซั่นเน้นความหลอนรายคืนจากคลิปตีสามและความผิดปกติเล็กๆ ในตึก เช่น ลิฟต์ที่ชอบจอดชั้น 13 เองและเพื่อนบ้านที่ไม่สบตาใคร ช่วงกลางพราวจับมือกับ รปภ. กะดึกไล่แกะคลิปเก่าจนพบรายชื่อผู้เช่าที่หายตัวไปทีละคนทุกๆ สิบสามคืน และเริ่มรู้ว่าตัวเองเหลือเวลาไม่กี่คืน ช่วงพีคความจริงเรื่องศพช่างในช่องฝ้าถูกเปิดโปงพร้อมกับที่เงาในคลิปเดินมาถึงหน้ากล้อง และนิติบุคคลพยายามปิดปากพราวด้วยทุกวิธี ช่วงท้ายพราวต้องเลือกระหว่างหนีออกจากตึกแบบคนก่อนๆ ที่สุดท้ายไม่มีใครรอด หรือหันกลับไปมองสิ่งที่เธอหนีมาตลอด ทั้งศพในฝ้าและความผิดของตัวเอง โดยราคาของการมองความจริงครั้งนี้อาจคือการต้องเป็นคนถือกล้องต่อไป",
