    "mainPlot": "ใบเตย พยาบาลสาวจากกรุงเทพฯ กลับหมู่บ้านริมแม่น้ำในภาคกลางเพื่อจัดงานศพยายผู้เลี้ยงเธอมา ระหว่างเก็บของเธอพบว่ายายสั่งเสียให้จุดตะเกียงหน้าเรือนไทยร้างท้ายสวนทุกค่ำโดยห้ามขาดแม้แต่คืนเดียว และห้ามรับคำเชิญขึ้นเรือนไม่ว่าเสียงในนั้นจะอ้อนวอนเพียงใด ใบเตยไม่เชื่อเรื่องงมงายจึงปล่อยตะเกียงดับในคืนที่สาม แล้วเสียงมโหรีกับเสียงแม่เพลงร้องรับขวัญก็ลอยข้ามสวนมาพร้อมกลิ่นดอกไม้สดทั้งที่รอบเรือนมีแต่หญ้าแห้ง ชาวบ้านผู้เฒ่าจึงยอมเล่าความจริงว่าเรือนหลังนั้นคือเรือนหอของย่าทวดเภา เจ้าสาวที่ถูกทั้งตระกูลจับกดน้ำตายในคืนแต่งงานเพราะไปรู้ความลับเรื่องที่ดินที่ตระกูลโกงมาจากวัด ยายของใบเตยคือคนสุดท้ายที่รับหน้าที่จุดตะเกียงขอขมาต่างหน้าคนทั้งตระกูล กติกาของเรือนคือ ตราบใดที่ไฟรับขวัญยังสว่าง ย่าทวดเภาจะรอต่อไป แต่ถ้าไฟดับ นางจะออกมาตามทวงเลือดของคนตระกูลนี้ทีละคน และตอนนี้คนของตระกูลที่เหลืออยู่คนสุดท้ายก็คือใบเตยเอง ปมที่ซ่อนอยู่คือใบเตยต้องเลือกว่าจะรักษาชีวิตตัวเองด้วยการทำตามธรรมเนียมต่อไปเรื่อยๆ หรือกล้าขุดความอยุติธรรมเมื่อห้าสิบปีก่อนขึ้นมาคืนความเป็นธรรมให้ผู้ตายจริงๆ",
