    "mainPlot": "กฤช เซลส์ขายบ้านจัดสรรที่กำลังจะถูกไล่ออกและมีแม่ป่วยรอเงินผ่าตัด ตัดสินใจไปบนกับศาลเจ้าแม่ตะเคียนทองริมโครงการร้างตามคำแนะนำของแม่ค้าหวยแถวนั้น เขาขอสามอย่างคือยอดขายอันดับหนึ่ง เงินก้อนรักษาแม่ และผู้หญิงที่เขาแอบชอบ พร้อมสัญญาปากเปล่าว่าจะถวายละครชาตรีเจ็ดวันกับสร้อยทองหนึ่งบาท ทุกอย่างเป็นจริงภายในสามเดือนจนกฤชลืมคำสัญญาและย้ายเข้าเมืองไปใช้ชีวิตใหม่ กระทั่งของที่ขอเริ่มถูกทวงคืนตามลำดับที่เคยขอ ยอดขายพังเพราะลูกค้าทุกคนฝันร้ายถึงผู้หญิงในชุดไทยยืนอยู่ในบ้านตัวอย่าง เงินก้อนหายไปกับอุบัติเหตุประหลาด และคนรักเริ่มละเมอพูดด้วยเสียงที่ไม่ใช่ของเธอ กติกาของอาถรรพ์นี้ชัดเจนและยุติธรรมอย่างเยือกเย็น คือเจ้าแม่ไม่เคยโกงใคร แต่ไม่เคยยกหนี้ให้ใครเช่นกัน ของที่บนแล้วไม่แก้จะถูกทวงคืนเป็นสามเท่า และห้ามตัดต้นตะเคียนที่เป็นที่สิงสถิตเด็ดขาด ปมที่ซ่อนอยู่คือบริษัทของกฤชกำลังจะไถที่ดินแปลงนั้นทำเฟสใหม่ และคนเซ็นอนุมัติแบบก่อสร้างทับศาลก็คือกฤชเอง เขาจึงต้องเลือกระหว่างหน้าที่การงานที่ขอมากับการปกป้องสิ่งที่ให้ทุกอย่างแก่เขา ก่อนที่หนี้ก้อนสุดท้ายจะถูกทวงด้วยชีวิตแม่ของเขา",
    "seasonArc": "ช่วงต้นซีซั่นเล่าการบนและความสำเร็จที่ไหลมาเทมาแบบผิดปกติ สลับกับลางร้ายเล็กๆ เช่น กลิ่นธูปในห้องนอนและด้ายแดงที่ผูกข้อมือเองตอนหลับ ช่วงกลางการทวงคืนเริ่มไต่ระดับจากเรื่องงานไปสู่คนใกล้ตัว กฤชไปขอความช่วยเหลือจากหมอธรรมที่เผยว่าคนที่บนแล้วเบี้ยวศาลนี้มีมาก่อนหน้าเขาหลายคน และไม่มีใครจบสวย ช่วงพีคบริษัทเดินหน้าไถที่ทับศาลทั้งที่กฤชคัดค้าน ทำให้อาถรรพ์ลามจากเรื่องส่วนตัวกลายเป็นโศกนาฏกรรมทั้งโครงการ คนงานเห็นผู้หญิงยืนบนคานทุกคืนและเครื่องจักรทำงานเองได้ ช่วงท้ายกฤชค้นพบว่าเจ้าแม่ตะเคียนแท้จริงคือหญิงสาวที่ถูกนายทุนรุ่นก่อนโกงที่ดินแล้วผูกคอกับต้นตะเคียนเมื่อหลายสิบปีก่อน การแก้บนที่แท้จริงจึงไม่ใช่ละครชาตรีหรือสร้อยทอง แต่คือการคืนความจริงและที่ดินให้เจ้าของเดิม ซีซั่นจบที่กฤชยอมสละทุกอย่างที่เคยขอเพื่อปลดหนี้ พร้อมทิ้งปมว่าคำขอข้อที่สามของเขายังไม่ถูกทวงคืน",
