    "mainPlot": "เรื่องราวเกิดขึ้นในตลาดเก่าริมน้ำของเมืองเล็กๆ ปี พ.ศ. 2512 ยุคที่วิทยุทรานซิสเตอร์กำลังเข้ามาแทนที่ลิเกหน้าโรง และหนังกลางแปลงเริ่มแย่งคนดูจากโรงหนังไม้สแตนด์อโลน สายหยุด ลูกสาวคนเดียวของเถ้าแก่โรงหนังศรีบันเทิง มีพรสวรรค์ด้านการพากย์หนังและเล่าเรื่อง แต่พ่อหัวโบราณห้ามเด็ดขาดเพราะถือว่าผู้หญิงไม่ควรออกหน้า เธอจึงแอบขี่จักรยานไปสถานีวิทยุประจำจังหวัดทุกค่ำ จัดรายการเพลงลูกกรุงและอ่านจดหมายผู้ฟังใต้นามแฝงว่าดาวประดับฟ้า จนกลายเป็นเสียงที่ทั้งอำเภอตั้งวงรอฟัง ขณะเดียวกัน ประยงค์ หนุ่มนักเรียนนอกถูกบริษัทหนังจากพระนครส่งมาเจรจาซื้อกิจการโรงหนังที่ขาดทุน เขาตกหลุมรักเสียงของดาวประดับฟ้าผ่านคลื่นวิทยุ และตกหลุมรักสายหยุดตัวจริงที่ปะทะคารมกับเขากลางตลาดโดยไม่รู้ว่าเป็นคนเดียวกัน ความลับซ้อนความลับเมื่อสายหยุดพบกล่องฟิล์มเก่าในห้องฉาย ที่บันทึกภาพแม่ผู้ล่วงลับของเธอเคยเป็นนักแสดงหนังไทยก่อนถูกบังคับให้ทิ้งวงการมาแต่งงาน ยิ่งใกล้วันเซ็นสัญญาขายโรงหนัง เธอยิ่งต้องเลือกระหว่างความฝัน ความรัก และการรักษาลมหายใจสุดท้ายของครอบครัวไว้ให้พ่อ",
