    "mainPlot": "พิมพ์ลดา สถาปนิกสาวสายอนุรักษ์ยุคปัจจุบัน รับงานสำรวจตึกแถวโบราณย่านการค้าเก่าที่กำลังจะถูกทุบ เธอพบนาฬิกาพกทองเหลืองสลักชื่อเจ้าของฝังอยู่ในผนัง และเมื่อเข็มนาฬิกาที่ตายมานานกลับเดินอีกครั้ง เธอก็ลืมตาตื่นกลางตลาดเดียวกันในปี พ.ศ. 2498 ยุคที่ย่านนี้ยังรุ่งเรืองสุดขีด พิมพ์ลดาผู้พูดจาแปลกหู แต่งตัวประหลาด และไม่มีบัตรประจำตัว ถูกช่วยไว้โดยการัณย์ นายช่างหนุ่มเจ้าของห้างขายยาผู้เป็นเจ้าของนาฬิกาพกเรือนนั้น เธอจำได้ทันทีจากงานวิจัยของตัวเองว่าย่านนี้จะเกิดเพลิงไหม้ครั้งใหญ่ในอีกไม่กี่สิบวัน และชื่อของการัณย์อยู่ในบันทึกรายชื่อผู้เสียชีวิต ระหว่างพยายามปรับตัวกับโลกที่ไม่มีโทรศัพท์มือถือ ต้องหุงข้าวด้วยเตาถ่านและระวังคำพูดทุกประโยค เธอค่อยๆ สืบพบว่าเพลิงไหม้ครั้งนั้นอาจไม่ใช่อุบัติเหตุ แต่เกี่ยวพันกับขบวนการปล่อยกู้นอกระบบที่หวังฮุบที่ดินทั้งย่าน ยิ่งแก้ไขอดีตมากเท่าไร เธอยิ่งพบว่าบางเหตุการณ์ดิ้นกลับเข้าเส้นเดิมเสมอ และความลับที่เจ็บปวดที่สุดคือความเชื่อมโยงระหว่างตระกูลของการัณย์กับครอบครัวของเธอเองในปัจจุบัน",
    "seasonArc": "ช่วงต้นเรื่องเน้นความปั่นป่วนขบขันของสาวยุคใหม่ที่ต้องเอาตัวรอดในปี 2498 พร้อมปูสัมพันธ์กับการัณย์และผู้คนในตลาด ช่วงกลางเรื่องพิมพ์ลดาเริ่มใช้ความรู้จากอนาคตช่วยกิจการของชาวบ้านจนถูกนายทุนเงินกู้หมายหัว ขณะเดียวกันก็พบหลักฐานว่าไฟไหม้ในประวัติศาสตร์มีคนจุด และทุกครั้งที่เธอเปลี่ยนรายละเอียดเล็กๆ นาฬิกาพกจะเดินเร็วขึ้นเหมือนเตือนว่าเวลาของเธอกำลังหมด จุดพีคคือคืนเกิดเหตุจริงที่เธอต้องเลือกระหว่างช่วยคนทั้งตลาดหรือช่วยการัณย์คนเดียว พร้อมเฉลยว่าคนจุดไฟคือคนที่เธอไว้ใจที่สุดในยุคนั้น ตอนจบซีซั่นเธอถูกดึงกลับปัจจุบันกลางเปลวเพลิงโดยไม่รู้ผลลัพธ์ และพบว่าปัจจุบันที่เธอกลับมาไม่เหมือนเดิมอีกต่อไป โดยมีชายชราคนหนึ่งถือนาฬิกาพกเรือนเดียวกันมารอพบเธอหน้าตึกแถว",
