    "visualBible": "ภาพสองยุคต้องต่างกันชัดเจน ยุคปัจจุบันใช้โทนเย็นฟ้าอมเทา แสงนีออนและกระจกตึกสูง ภาพคมสะอาด ส่วนปี พ.ศ. 2498 ใช้โทนอุ่นซีเปียอมทอง แสงแดดจัดแบบเมืองร้อน คอนทราสต์นุ่มเหมือนภาพถ่ายฟิล์มยุคเก่า ฉากหลักคือย่านตึกแถวปูนสองชั้นแบบชิโนโปรตุกีสผสมห้องแถวไม้ ป้ายร้านทองอักษรจีนไทยวาดมือ ห้างขายยาที่มีตู้ยาไม้ลิ้นชักเล็กนับร้อย โคมไฟน้ำมันและพัดลมตั้งโต๊ะโลหะ รถลากและรถยนต์ทรงโค้งจอดปนกัน เสื้อผ้ายุคเก่าเป็นชุดเดรสเอวจีบคอปกและผ้าถุงกับเสื้อลูกไม้สำหรับผู้หญิง สูทลินินสีอ่อนและหมวกสักหลาดสำหรับผู้ชาย ตัดกับชุดเสื้อเชิ้ตโอเวอร์ไซซ์กางเกงยีนส์ของพิมพ์ลดาที่โดดออกจากฉากอย่างจงใจในตอนต้นเรื่อง ฉากไฟไหม้ใช้โทนส้มแดงจัดกับควันดำเป็นภาพจำของซีซั่น"
