    "mainPlot": "เมื่อสิบปีก่อน ดาวเรืองยืนอยู่หน้าทางเลือกครั้งใหญ่ที่สุดในชีวิต ระหว่างขึ้นรถทัวร์เข้ากรุงเทพไปตามความฝันนักร้อง หรืออยู่บ้านต่างจังหวัดดูแลแม่ที่เพิ่งล้มป่วยและรับช่วงร้านตัดเย็บของครอบครัว เรื่องราวเล่าคู่ขนานสองโลกที่แยกจากกันในวินาทีนั้น โลกแรกเธอคือดาวา นักร้องชื่อดังที่มีทุกอย่างยกเว้นครอบครัว เพราะแม่เสียไปโดยที่เธอไม่ทันกลับไปส่ง โลกที่สองเธอคือเจ๊ดาวแห่งร้านเย็บผ้า ผู้มีแม่ มีบ้าน มีคนรักเก่าอยู่ข้างกัน แต่เก็บความฝันไว้ในลิ้นชักจนมันกลายเป็นแผลเงียบๆ คืนหนึ่งโทรศัพท์บ้านเครื่องเก่าของแม่ที่เสียมานานกลับดังขึ้นพร้อมกันในสองโลก และปลายสายคือตัวเธอเองอีกคน ทั้งสองเริ่มแลกเปลี่ยนข้อมูลเพื่ออุดรอยแผลของกันและกัน ดาวาใช้ความรู้วงการช่วยเจ๊ดาวปั้นเสียงอีกครั้ง เจ๊ดาวช่วยดาวาไขปริศนาว่าแม่ป่วยเพราะอะไรกันแน่ จนพบความลับว่าอาการป่วยของแม่ในอดีตเกี่ยวข้องกับหนี้ก้อนลับที่พ่อผู้หายตัวไปทิ้งไว้ ยิ่งสายโทรศัพท์เชื่อมสองโลกบ่อยขึ้น เส้นแบ่งยิ่งบางลง ความทรงจำของคนรอบตัวเริ่มปนกัน และเสียงสัญญาณที่ค่อยๆ ขาดหายบอกพวกเธอว่าอีกไม่นานจะเหลือโลกได้เพียงใบเดียว",
    "seasonArc": "ช่วงต้นเรื่องเปิดชีวิตคู่ขนานของดาวเรืองทั้งสองแบบตัดสลับ ให้คนดูเห็นว่าแต่ละโลกได้บางอย่างมาและเสียบางอย่างไป ก่อนจบช่วงด้วยโทรศัพท์สายแรกที่ทั้งคู่ต่างคิดว่าเป็นเรื่องแกล้งกัน ช่วงกลางเรื่องทั้งสองร่วมมือกันแก้ปมของอีกฝ่าย ความสำเร็จเล็กๆ เริ่มเกิดขึ้นในทั้งสองโลก แต่ผลข้างเคียงก็ตามมา ทั้งคนรอบตัวที่ฝันเห็นอีกชีวิตหนึ่ง และเหตุการณ์สองโลกที่เริ่มสะท้อนกันอย่างน่าขนลุก จุดพีคคือการเฉลยความลับเรื่องหนี้ของพ่อและตัวตนของชายลึกลับที่ปรากฏในทั้งสองโลกพร้อมกัน ผู้รู้กติกาของสายโทรศัพท์ข้ามมิติดีกว่าใคร ตอนจบซีซั่นสัญญาณโทรศัพท์กำลังจะดับถาวร ดาวเรืองทั้งสองต้องตัดสินใจครั้งสุดท้ายว่าใครจะได้ไปต่อ หรือจะเสี่ยงทำสิ่งที่ไม่มีใครเคยทำ คือแลกโลกกันทั้งชีวิต โดยตอนสุดท้ายจบที่เสียงกริ่งโทรศัพท์ดังขึ้นอีกครั้งในโลกที่สาม",
