    "mainPlot": "ปลายยุคกรุงศรีอยุธยา ยามศึกใหญ่กำลังคืบใกล้พระนคร ทับ ช่างตีดาบหนุ่มฝีมือเอกแห่งหมู่บ้านช่างริมแม่น้ำ ใช้ชีวิตเรียบง่ายกับการตีเหล็กส่งกองทัพและแอบผูกใจกับเรียม แม่ค้าเรือลูกสาวหมอยาประจำหมู่บ้าน ชีวิตพลิกคว่ำเมื่อดาบตราประจำเตาของเขาไปปรากฏในกองอาวุธเถื่อนที่ลักลอบส่งออกนอกด่าน ทับถูกตราหน้าว่าเป็นคนทรยศต่อแผ่นดิน ครูช่างผู้เลี้ยงเขามาเหมือนพ่อถูกจับ และหมู่บ้านช่างถูกสั่งเฝ้าระวังทั้งที่ศึกกำลังใกล้เข้ามาทุกวัน ก่อนถูกจับ ครูช่างฝากสมุดข่อยบัญชีลับไว้กับทับ ในนั้นบันทึกเส้นทางเหล็กและรายชื่อที่โยงถึงขุนนางฉ้อฉลผู้ลักลอบขายอาวุธหาประโยชน์จากสงคราม ทับกับเรียมจึงต้องหนีตามลำน้ำ ปลอมตัวปะปนไปกับขบวนเรือค้าขาย รวบรวมพยานหลักฐานจากคนตัวเล็กตัวน้อยที่เคยถูกขุนนางผู้นี้เหยียบย่ำ ทั้งฝีพาย แม่ค้า และไพร่หนีทัพ ขณะเดียวกันทหารหนุ่มผู้ตงฉินที่ได้รับคำสั่งให้ตามล่าทับ ก็เริ่มสงสัยว่าความจริงอาจไม่ใช่อย่างที่เบื้องบนของตนบอก เรื่องราวของคนตัวเล็กที่ไม่มีทั้งยศและอำนาจ แต่เลือกยืนข้างความถูกต้องด้วยชีวิต ท่ามกลางแผ่นดินที่กำลังสั่นคลอน",
    "seasonArc": "ช่วงต้นเรื่องปูชีวิตหมู่บ้านช่างตีดาบและความรักใสซื่อของทับกับเรียม ก่อนพลิกเป็นหนีตายเมื่อดาบตราประจำเตาไปโผล่ในกองอาวุธเถื่อนและครูช่างถูกจับ ช่วงกลางเรื่องคือการเดินทางตามลำน้ำเพื่อตามหาพยานทีละคน แต่ละตอนเผยหน้าเครือข่ายของขุนนางฉ้อฉลลึกขึ้น พร้อมเกมไล่ล่ากับหมื่นแสนศึกที่ค่อยๆ เปลี่ยนจากผู้ล่าเป็นผู้ตั้งคำถาม จุดพีคคือเมื่อขุนนางตัดสินใจเผาหมู่บ้านช่างเพื่อทำลายหลักฐานทั้งหมด บีบให้ทับต้องกลับไปเผชิญหน้าทั้งที่รู้ว่าเป็นกับดัก ตอนจบซีซั่นคือการเปิดโปงบัญชีลับต่อหน้าผู้พิพากษาศึกกลางค่ายทหาร ล้างมลทินให้ครูช่างได้สำเร็จ แต่ข่าวศึกใหญ่ก็มาถึงพร้อมกัน ทับหลอมดาบเล่มงามที่สุดในชีวิตแล้วเดินเข้าสู่สนามรบ ทิ้งคำสัญญากับเรียมไว้ที่ท่าน้ำว่าจะกลับมา",
