    "mainPlot": "Maya is an ordinary office worker juggling three jobs to support her younger brother, never knowing that her real father was the heir of the mighty Sivakul dynasty who vanished twenty years ago. When the gravely ill family patriarch hires investigators to find his true grandchild — before the impostors and schemers inside the family can seize everything — Maya is pulled into a high-society world of household politics and contemptuous relatives who refuse to accept her. But the harder she works to prove herself, the clearer it becomes that someone in the family would rather see her dead than inheriting.",
    "seasonArc": "Early on, Maya is brought to the mansion and must survive the scorn of relatives terrified of losing their share. Through the middle episodes she gradually proves her business talent, winning over her grandfather and the company's loyal veterans, even as a cousin desperate to be sole heir escalates from smears to outright attempts on her life. The story peaks with the discovery that her father's disappearance twenty years ago was no accident but a murder plotted from inside the house — driving Maya to gather the evidence and expose the truth before the entire family on the day the will is read.",
