    "logline": "When the patriarch of a great dynasty dies suddenly without signing his will, five half-siblings must fight for the single heir's seat — and family love turns into a battlefield.",
    "mainPlot": "The Jiranuwat family, owners of a nationwide real-estate and hotel empire, is rocked when the patriarch dies suddenly in a suspicious accident, leaving behind only an unfinished will. His five children — born to three different wives — must gather at the family mansion to prove who is the rightful heir worthy of the empire. Sibling bonds that once seemed normal crack apart as everyone starts digging up secrets, forging documents, and betraying one another for shares and the CEO's chair. Amid the chaos, the overlooked youngest child turns out to be the only one who uncovers the truth about their father's death.",
    "seasonArc": "The season opens with a will reading that plunges the family into chaos, as siblings form shifting temporary alliances to take each other down. In the middle stretch the war escalates into exposed personal secrets, forged company documents, and outside players circling to swallow the business whole. The story then plunges toward crisis with the revelation that the father's death was no accident — someone in the family was behind it. The season finale is a last showdown in the shareholders' meeting room, where both the company's future and the fate of the entire family will be decided.",
