    "mainPlot": "Prawee works as the personal secretary to Korrawee, the famously icy, exacting president of a major real-estate empire. Everything flips when Korrawee's family pressures him into marrying the heiress of a rival dynasty to seal a business alliance. To buy time, he offers Prawee a contract: play his temporary girlfriend in exchange for a life-changing bonus. The two must perform affection in public while keeping their walls up in private — but the closer they get, in the office and after hours, the blurrier the line between the fake role and real feelings becomes. Meanwhile, Korrawee's former fiancee and a buried family secret creep steadily closer, threatening to destroy everything they've built.",
    "seasonArc": "The season opens with power struggles in the office and the strict rules of the fake-dating contract that both leads must grit their teeth to follow. In the middle stretch, the relationship deepens through workplace crises and an out-of-town business trip — until the press photographs them together and the family starts questioning whether the romance is real. In the final act, the former fiancee exposes the secret contract in front of everyone, forcing Korrawee to choose between his family's interests and his own heart, before the finale delivers a love declaration in the middle of a shareholders' meeting that turns every power play upside down.",
