    "category": "fake-dating-contract",
    "logline": "Cornered into an arranged match by her family, an office worker hires a stranger to play her boyfriend for one family reunion — but a one-night contract keeps extending until neither can tell who's fooling whom.",
    "mainPlot": "Mintra, an office worker being pushed by her elders into an arranged marriage with a business owner's son, hires Pawarit, an out-of-work actor, to play her boyfriend for a single family reunion. The plan refuses to die: her family adores him and keeps summoning the couple back for one important occasion after another. The fake-dating contract — with its strict rule against catching real feelings — gets tested every time they have to act sweet in public, until the line between performance and genuine emotion all but disappears. And just when things couldn't get messier, Mintra's ex-boyfriend storms back into her life at the worst possible moment.",
