    "seasonArc": "The season opens with cutthroat competition inside the training camp and the two leads colliding at every evaluation round. The middle episodes reveal the pressure each is hiding — families banking on their success, injuries concealed from the coaches — as late-night practice sessions pull them closer, until the agency announces there will be only one center and rumors of a forbidden relationship begin to spread. In the final act, both must choose between their dream on the stage and their own hearts, before a debut showcase finale proves they are good enough to stand side by side without having to compete at all.",
