    "visualBible": "A warm, moody late-night recording-studio aesthetic: amber glow from vintage bulbs against the darkness beyond the soundproof glass. Key settings include the recording booth, a small concert stage, and a rooftop overlooking the city lights after midnight. Wardrobe is understated indie-musician style — simple, but unmistakably personal."
