    "logline": "A small food-and-gift shop uses signature menu items as story keys, not hard ads, unlocking memories, relationships, and customer problems in every episode.",
    "mainPlot": "Fon inherits her mother's small food shop in an old tourist district and has to revive its signature menu without turning memory into a sales gimmick. Each episode begins with one food item or product: a chili paste bought to reconcile with a father, the last dessert box reconnecting ex-lovers, or a gift set delivered to the wrong family and revealing a secret.",
