async function seed() {
  console.log("Seeding Vertical Drama Series genre presets...\n");

  const sql = postgres(DATABASE_URL);

  try {
    const tableExists = await sql`
      SELECT EXISTS (
        SELECT FROM information_schema.tables
        WHERE table_name = 'vertical_drama_genre_presets'
      )
    `;

    if (!tableExists[0].exists) {
      console.log("ERROR: vertical_drama_genre_presets table does not exist. Run the migration first.");
      await sql.end();
      return;
    }

    const deleted = await sql`DELETE FROM vertical_drama_genre_presets WHERE scope = 'global' RETURNING id`;
    console.log(`Cleared ${deleted.length} existing global preset(s) (private presets untouched)\n`);

    const localeSets: Array<[string, GenrePresetSeed[]]> = [
      ["th", GENRE_PRESETS],
      ["en", GENRE_PRESETS_EN],
    ];
    for (const [locale, presetList] of localeSets) {
      let sortOrder = 0;
      for (const preset of presetList) {
        await sql`
          INSERT INTO vertical_drama_genre_presets (
            title, category, locale, logline, "mainPlot", "seasonArc",
            tone, "cliffhangerStyle", "charactersJson", "visualBible", "visualIdentityJson", "sortOrder"
          ) VALUES (
            ${preset.title},
            ${preset.category},
            ${locale},
            ${preset.logline},
            ${preset.mainPlot},
            ${preset.seasonArc},
            ${preset.tone},
            ${preset.cliffhangerStyle},
            ${JSON.stringify(preset.characters)},
            ${preset.visualBible},
            ${preset.visualIdentityJson ? JSON.stringify(preset.visualIdentityJson) : null},
            ${sortOrder}
          )
        `;
        console.log(
          `  + [${locale}] ${preset.title} (${preset.category})${preset.visualIdentityJson ? " [visual identity]" : ""}`,
        );
        sortOrder += 1;
      }
    }

    console.log(
      `\nSeeded ${GENRE_PRESETS.length} th + ${GENRE_PRESETS_EN.length} en genre presets.\n`,
    );
  } catch (error) {
    console.error("Error seeding genre presets:", error);
    throw error;
  } finally {
    await sql.end();
  }
}

seed().catch((e) => {
  console.error(e);
  process.exit(1);
});
